INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3086', 'spa', 'Jehoadán/Yehoadán, madre del rey Amasías de Judá', 'Nombre propio de la madre de Amasías, que aparece en las fórmulas de reinado del rey de Judá. Se registra en 2 Reyes 14:2 (con variantes Ketiv/Qeré: יהועדין/יהועדן) y en 2 Crónicas 25:1. Los estudiosos sugieren que podría ser una forma dual aramea o un plural femenino relacionado con la raíz עדה, con posibles conexiones al nombre divino Yahvé. La diversidad en las versiones antiguas (griego Ἰωαδειμ, Ἰωναα) y la comparación con nombres babilónicos indican un patrón onomástico inusual o arcaico, quizá reflejo de influencias sincretistas en el Judá del siglo IX a. C.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3087', 'spa', 'Josadac (''YHWH es justo''), sacerdote exiliado y padre de Josué, el sumo sacerdote de la restauración.', 'Nombre teofórico que significa ''YHWH es justo'', perteneciente al hijo del sumo sacerdote Seraías, quien fue ejecutado por Nabucodonosor en Ribla (2 R 25:18-21). Josadac mismo fue llevado al exilio babilónico (1 Cr 6:15), convirtiéndose en el eslabón entre el sacerdocio preexílico y el postexílico. Su hijo Josué (Jesúa) sirvió como primer sumo sacerdote del templo restaurado. El nombre aparece en su forma completa Yehōtsādāq en Hageo, Zacarías y Crónicas, y en la forma abreviada Yōtsādāq en Esdras y Nehemías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3088', 'spa', 'Jehoram/Joram -- nombre teofórico que significa ''YHWH es exaltado'', llevado por dos reyes y otras figuras bíblicas', 'Jehoram/Joram -- nombre teofórico que significa ''YHWH es exaltado'', llevado por dos reyes y otras figuras bíblicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3091', 'spa', 'Yehoshua (Josue) -- nombre propio que significa ''YHWH es salvacion''; sucesor de Moises y tambien el sumo sacerdote postexilico', 'Yehoshua es un nombre teoforico que combina YHWH con yasha (''salvar''), dando como resultado ''YHWH es salvacion''. Su portador mas prominente es Josue hijo de Nun, quien sucedio a Moises y condujo a Israel a traves del Jordan hasta la tierra prometida (Jos 1:1-2). El nombre pertenece tambien a Josue el sumo sacerdote de la comunidad postexilica (Hag 1:1; Zac 3:1). La forma contracta posterior Yeshua se convirtio en el nombre hebreo detras del griego Iesous -- Jesus --, haciendo de este nombre un puente entre el Antiguo y el Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3092', 'spa', 'Josafat — ''YHWH ha juzgado,'' nombre propio portado principalmente por el rey de Judá (hijo de Asa). El nombre יְהוֹשָׁפָט (Yehoshafat, ''YHWH ha juzgad', 'Josafat — ''YHWH ha juzgado,'' nombre propio portado principalmente por el rey de Judá (hijo de Asa). El nombre יְהוֹשָׁפָט (Yehoshafat, ''YHWH ha juzgado'') pertenece principalmente al rey justo de Judá que sucedió a su padre Asa y reinó durante un período de reforma religiosa y alianza militar (1 Re 22; 2 Cr 17–20). De las 84 apariciones, la gran mayoría se refieren a este rey, mientras que las restantes identifican a otros individuos: un cronista bajo David y Salomón (2 Sam 8:16), el padre del rey Jehú (2 Re 9:2), uno de los oficiales de aprovisionamiento de Salomón (1 Re 4:17) y guerreros de la guardia de élite de David (1 Cr 11:43). El nombre teofórico combina YHWH (יהו) con la raíz שׁפט (''juzgar'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3095', 'spa', 'Diamante o piedra preciosa dura (¿jaspe? ¿ónice?), incluida entre las gemas del pectoral sacerdotal', 'Piedra preciosa que aparece en las listas de gemas que adornaban el pectoral del sumo sacerdote (Éxodo 28:18; 39:11) y en la descripción de Ezequiel sobre la vestidura del rey de Tiro (28:13). Su identificación exacta sigue siendo incierta: las versiones antiguas sugieren jaspe (LXX, Vulgata) u ónice, mientras que la etimología hebrea, derivada de la raíz הלם («golpear, martillar»), apunta a una piedra apreciada por su dureza, capaz de cortar otros materiales. Las traducciones medievales y modernas la interpretan como «diamante», aunque los israelitas antiguos probablemente no tenían acceso a diamantes verdaderos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3096', 'spa', 'Jahaz, ciudad en Moab donde Israel derrotó a Sijón; después ciudad levítica asignada a Rubén.', 'Topónimo con diversas variantes ortográficas (Yahats, Yahtsah, Jahaz, Jahasá) que designa una ciudad en Moab, escenario de la batalla decisiva en la que Israel bajo Moisés venció a Sijón, rey de los amorreos (Nm 21:23; Dt 2:32). Esta victoria abrió la Transjordania al asentamiento israelita. La ciudad fue asignada a la tribu de Rubén (Jos 13:18) y posteriormente designada ciudad levítica (1 Cr 6:63). Reaparece en los oráculos proféticos contra Moab (Is 15:4; Jer 48:21, 34), donde su mención evoca el antiguo campo de batalla. La Estela de Mesa (líneas 19-20) también menciona Jahaz, confirmando su importancia histórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3097', 'spa', 'Joab -- nombre propio que significa ''YHWH es padre''; sobrino de David y comandante de su ejercito', 'Yoav es un nombre teoforico que combina una forma abreviada de YHWH con av (''padre''), resultando en ''YHWH es padre''. El nombre aparece 145 veces, abrumadoramente para el sobrino de David -- hijo de su hermana Servia --, quien sirvio como comandante del ejercito israelita durante todo el reinado de David (2 S 2:13; 1 R 2:5). Joab fue un general brillante pero despiadado: asesino a Abner (2 S 3:27), dirigio el asedio de Raba (2 S 11:1) y finalmente fue ejecutado por orden de Salomon (1 R 2:34). Dos personajes menores comparten el nombre: un descendiente de Juda (1 Cr 4:14) y una familia de la comunidad postexilica (Esd 2:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3098', 'spa', 'Joah (יוֹאָח) — ''YHWH es hermano''; nombre de cuatro personajes del AT, especialmente el cronista real de Ezequías', 'El nombre propio Joah (יוֹאָח, probablemente ''YHWH es hermano'') identifica a cuatro individuos distintos en el Antiguo Testamento. El más destacado es el hijo de Asaf, quien sirvió como cronista real (מַזְכִּיר) bajo el rey Ezequías y estuvo presente durante las tensas negociaciones con el Rabsaces asirio frente a los muros de Jerusalén (2 Re 18:18, 26, 37; Is 36:3, 11, 22). El nombre también aparece para un levita gersonita en la genealogía de David (1 Cr 6:21), un portero coraíta (1 Cr 26:4), un levita involucrado en la restauración del templo bajo Josías (2 Cr 34:8) y un levita que participó en la purificación del templo bajo Ezequías (2 Cr 29:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3099', 'spa', 'Joacaz/Yoajaz, ''Yahvé ha asido,'' nombre de reyes de Israel y Judá y del padre de un cronista', 'Nombre teofórico que significa ''Yahvé ha asido,'' presente tanto en su forma plena (Joacaz) como en una forma contraída (Yoajaz). Designa a varias figuras: un rey de Judá, hijo de Josías, que reinó solo tres meses antes de ser deportado a Egipto (2 Cr 36:2, 4); un rey de Israel, hijo de Jehú (2 R 14:1 en forma contraída); y el padre del cronista Joah bajo el reinado de Josías (2 Cr 34:8). El nombre es una variante de Ocozías, con el elemento divino reposicionado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3100', 'spa', 'Joel — nombre personal que significa ''YHWH es Dios,'' llevado por al menos trece individuos en la Biblia hebrea. Nombre personal teoforico compuesto de', 'Joel — nombre personal que significa ''YHWH es Dios,'' llevado por al menos trece individuos en la Biblia hebrea. Nombre personal teoforico compuesto del nombre divino Yah y El (''Dios''), que produce el significado ''YHWH es Dios.'' El nombre es llevado por numerosas figuras a lo largo de la historia de Israel, siendo el mas famoso el profeta Joel hijo de Petuel, pero tambien el hijo primogenito de Samuel (1 Sam 8:2), un principe simeonita, un jefe rubenita, varios musicos levitas y lideres de la comunidad postexilica. Las tradiciones en espanol, frances y aleman preservan una forma cercana a ''Joel,'' reflejando una transmision notablemente estable de este nombre a traves de siglos e idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3101', 'spa', 'Joás / Yehoash — nombre teofórico que significa ''YHWH ha dado'', portado por reyes de Judá e Israel y otras figuras bíblicas', 'Joás / Yehoash — nombre teofórico que significa ''YHWH ha dado'', portado por reyes de Judá e Israel y otras figuras bíblicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3103', 'spa', 'Jobab — nombre propio de varios personajes del AT: descendiente de Joctán, rey edomita, rey cananeo y dos benjaminitas.', 'Jobab (יוֹבָב, Yōvāv) aparece nueve veces en el Antiguo Testamento como nombre de al menos cinco individuos distintos. El más antiguo es un hijo de Joctán en la Tabla de las Naciones (Gn 10:29), lo que vincula el nombre con la genealogía arábiga primitiva. Un segundo Jobab reina como rey de Edom desde Bosra (Gn 36:33-34), mientras que un tercero es el rey de Madón que se une a la coalición cananea del norte contra Josué (Jos 11:1). Otros dos benjaminitas llevan este nombre en las genealogías del Cronista (1 Cr 8:9, 18). La Septuaginta lo translitéra uniformemente como Ιωβαβ en todos los casos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3104', 'spa', 'Cuerno de carnero; el año jubilar proclamado por su toque, que marca libertad, restitución de tierras y condonación de deudas cada cincuenta años', 'Cuerno de carnero; el año jubilar proclamado por su toque, que marca libertad, restitución de tierras y condonación de deudas cada cincuenta años');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3107', 'spa', 'Jozabad (יוֹזָבָד) — ''YHWH ha otorgado''; nombre teofórico de varios levitas y guerreros del AT', 'El nombre יוֹזָבָד (Yozavad), que significa ''YHWH ha otorgado'' o ''YHWH ha concedido'', lo llevan al menos ocho individuos diferentes en los libros históricos y Crónicas. Dos guerreros gaditas que desertaron para unirse a David en Siclag llevaban este nombre (1 Cr 12:5, 21). Otros Jozabad aparecen como levitas encargados de los tesoros y contribuciones del templo bajo Ezequías (2 Cr 31:13) y Josías (2 Cr 35:9), así como un levita que participó en el pesaje de la plata y el oro de los exiliados que regresaban (Esd 8:33). Uno de los Jozabad figuraba entre quienes habían tomado esposas extranjeras (Esd 10:22-23). El elemento teofórico del nombre subraya la generosidad divina como tema de designación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3110', 'spa', 'Yojanán (''YHWH es misericordioso''); nombre personal llevado por sacerdotes, levitas, líderes militares y otros', 'Yojanán (''YHWH es misericordioso''); nombre personal llevado por sacerdotes, levitas, líderes militares y otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3111', 'spa', 'Joiada (Joiada); nombre propio que significa ''el SENOR conoce''', 'Nombre propio teoforico compuesto de Yahve (yeho) y la raiz yada'' (''conocer''), que da el significado ''el SENOR conoce''. En Nehemias, este nombre se refiere principalmente a figuras sacerdotales: Joiada hijo de Eliasib el sumo sacerdote (Neh 13:28), y miembros del linaje sacerdotal posexilico registrados en listas genealogicas (Neh 12:10-11, 22). La forma Yoyada'' es una variante abreviada del nombre completo Yehoyada''. Todas las traducciones principales — ingles ''Joiada'', espanol ''Joiada'', frances ''Jojada'' — preservan el elemento teoforico de manera uniforme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3113', 'spa', 'Joiacim, ''Yahvé levanta,'' sumo sacerdote del período postexílico, hijo de Jesúa', 'Forma contraída del nombre teofórico Joaquim que significa ''Yahvé levanta,'' designando aquí al sumo sacerdote postexílico hijo de Jesúa y padre de Eliasib (Neh 12:10, 12, 26). A diferencia del más conocido rey Joaquim de Judá, este Joiacim pertenece a la genealogía sacerdotal que sostuvo la comunidad restaurada de Jerusalén. Las cuatro apariciones se encuentran en el registro sacerdotal de Nehemías 12.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3114', 'spa', 'Joiarib (Jehoiarib); nombre propio teofórico que significa ''el SEÑOR contiende/aboga''', 'Nombre teofórico que combina a Yahvé con la raíz רִיב (''contender, abogar en un caso''), significando ''el SEÑOR aboga'' o ''el SEÑOR contiende''. Jehoiarib encabeza la primera de las veinticuatro divisiones sacerdotales (1 Cr 24:7) y aparece en las listas postexílicas de Nehemías y Esdras. En Esd 8:16, Joiarib es uno de los líderes enviados a reclutar levitas para el retorno. La forma abreviada יוֹיָרִיב alterna con יְהוֹיָרִיב en Crónicas y Nehemías. Todas las versiones mantienen la transliteración estable como ''Joiarib''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3117', 'spa', 'día, tiempo, época; período de vida; luz diurna; forma dual: dos días; expresión comparativa: como los días de', 'La palabra hebrea יוֹם es engañosamente simple —''día''— pero carga un peso semántico enorme en las Escrituras. Puede significar un período literal de 24 horas, las horas de luz en contraste con la noche, una fecha concreta, toda una era (''en los días de'') o la vida entera de alguien (''todos los días de su vida''). Combinada con preposiciones forma numerosos modismos: ''en aquel día,'' ''en aquellos días,'' ''de día en día.'' La evidencia multilingüe confirma esta amplitud, mientras que la construcción comparativa ''como los días de'' (Gn 29:20) muestra que יוֹם codifica calidad experiencial, no solo cantidad cronológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3118', 'spa', 'dia, dias (arameo) — unidad de tiempo en las porciones arameas de Daniel y Esdras, usada para fechas, duraciones y eras. El cognado arameo del hebreo ', 'dia, dias (arameo) — unidad de tiempo en las porciones arameas de Daniel y Esdras, usada para fechas, duraciones y eras. El cognado arameo del hebreo yom, que aparece exclusivamente en las secciones arameas de Daniel y Esdras. Cumple el mismo amplio rango que su contraparte hebrea: marca un dia especifico del calendario (Esd 6:15), expresa repeticion diaria en el modismo ''dia por dia'' (Esd 6:9), y se extiende a periodos mas largos como vidas y reinados (Dan 2:44; 5:11). La notable frase ''Anciano de Dias'' (attiq yomin, Dan 7:9, 13, 22) retrata a Dios como un soberano anciano cuyo dominio se extiende a traves de todas las epocas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3119', 'spa', 'De día, durante el día — adverbio temporal que marca acciones que ocurren durante las horas de luz. Yomam es el equivalente adverbial de laylah (''de n', 'De día, durante el día — adverbio temporal que marca acciones que ocurren durante las horas de luz. Yomam es el equivalente adverbial de laylah (''de noche''), y juntos forman uno de los merismos más característicos del hebreo para expresar actividad continua e incesante. Sus 51 apariciones pintan un cuadro vívido de la guía incesante de Dios: la columna de nube de día y de fuego de noche que guió a Israel por el desierto (Éx 13:21–22; Nm 14:14; Neh 9:12, 19), la sombra contra el calor de día y refugio contra la tormenta (Is 4:6), y el amor firme que el SEÑOR ordena ''de día'' mientras su cántico acompaña ''de noche'' (Sal 42:8). Jeremías usa el par yomam-laylah para describir el pacto inquebrantable de Dios con la creación misma (Jer 33:20, 25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3120', 'spa', 'Javán (יָוָן): hijo de Jafet, ancestro epónimo de los jonios; por extensión, Grecia como entidad geográfico-política', 'El nombre hebreo que designa tanto a la persona Javán, hijo de Jafet, como a la tierra de Grecia. En la Tabla de las Naciones (Gn 10:2, 4; 1 Cr 1:5, 7), Javán aparece como un ancestro individual cuyos descendientes incluyen a Elisá, Tarsis, Quitim y Dodanim, pueblos asociados con las costas del Egeo y el Mediterráneo. En la literatura profética posterior, particularmente Daniel (8:21; 10:20; 11:2) y Zacarías (9:13), el nombre designa a Grecia como potencia mundial. La LXX lo traduce como Ἑλλάς, y las inscripciones persas antiguas confirman la forma Yauna para los jonios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3122', 'spa', 'Jonadab (Yonadab/Yehonadab), nombre propio que significa ''YHWH es noble/generoso'', llevado por el sobrino de David y el patriarca recabita', 'Jonadab es un nombre que llevan dos personajes muy distintos. El sobrino de David, Jonadab hijo de Simea, aparece en el oscuro relato del crimen de Amnón contra Tamar, donde actúa como astuto consejero que idea el engaño (2 S 13:3-5, 32, 35). El otro Jonadab, hijo de Recab, es el venerado antepasado de los recabitas, cuyo voto de abstinencia del vino, la agricultura y las viviendas permanentes es presentado por Jeremías como modelo de obediencia fiel (Jer 35:6-19). La forma extendida Yehonadab aparece en 2 Reyes 10:15-23, donde este recabita se une a la purga de Jehú contra el culto a Baal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3123', 'spa', 'Paloma; el ave literal usada en sacrificios y símiles, o un término cariñoso de afecto para la amada', 'Paloma; el ave literal usada en sacrificios y símiles, o un término cariñoso de afecto para la amada');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3124', 'spa', 'Jonas — nombre personal que significa ''paloma,'' el profeta hijo de Amitai enviado a Ninive. Nombre propio del profeta Jonas (hebreo Yonah, ''paloma''), ', 'Jonas — nombre personal que significa ''paloma,'' el profeta hijo de Amitai enviado a Ninive. Nombre propio del profeta Jonas (hebreo Yonah, ''paloma''), hijo de Amitai, de Gat-hefer. Segun 2 Reyes 14:25, profetizo la restauracion territorial lograda bajo Jeroboam II. Es la figura central del Libro de Jonas, famoso por su mision renuente a Ninive y el episodio del gran pez. El significado de su nombre — ''paloma'' — simbolo de mansedumbre y vulnerabilidad, contrasta ironicamente con la obstinada huida del profeta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3127', 'spa', 'Brote tierno, vástago o rama nueva que crece de un árbol o vid; usado literal y figuradamente para la renovación de Israel.', 'Este sustantivo femenino (יוֹנֶקֶת) designa un brote fresco y tierno, un vástago o rama nueva del tipo que surge de una planta establecida. Siempre aparece con sufijos pronominales (''sus brotes'', ''sus retoños''), enfatizando la conexión orgánica entre la planta madre y el crecimiento nuevo. En Job 8:16 y 15:30, los brotes simbolizan la prosperidad engañosa de los impíos. Con mayor esperanza, Job 14:7 afirma que incluso un árbol talado puede echar retoños. El uso profético es ricamente metafórico: Hosea 14:7 retrata a Israel restaurado extendiendo ramas como un olivo, Ezekiel 17:22 imagina un vástago tierno de la copa del cedro, y Psalm 80:11 recuerda la vid cuyas ramas llegaban hasta el mar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3129', 'spa', 'Jonatán — ''YHWH ha dado''; hijo de Saúl y amigo entrañable de David, además de otras figuras bíblicas', 'Jonatán — ''YHWH ha dado''; hijo de Saúl y amigo entrañable de David, además de otras figuras bíblicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3130', 'spa', 'Jose -- nombre propio que significa ''el anade''; el patriarca, y por metonimia las tribus norteñas descendientes de el', 'Yosef es un nombre propio explicado por dos etimologias populares en Genesis 30:23-24: Raquel dice que Dios ha ''quitado'' (asaf) su afrenta y luego ruega que YHWH ''anadira'' (yasaf) otro hijo. El referente principal del nombre es el patriarca Jose, el hijo predilecto de Jacob, cuya historia de traicion, esclavitud y exaltacion domina Genesis 37-50. Por metonimia, ''Jose'' designa tambien el territorio tribal septentrional de Efrain y Manases (Dt 33:13; Sal 80:2). La doble etimologia conecta la experiencia personal de Raquel con la promesa divina de multiplicacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3136a', 'spa', 'Josadac, ''Yahvé es justo,'' padre de Josué el sumo sacerdote de la restauración', 'Forma contraída del nombre Jehosadac que significa ''Yahvé es justo,'' identificando al padre de Josué (Jesúa), el sumo sacerdote que dirigió el culto en el templo reconstruido. El nombre vincula la legitimidad sacerdotal a través del exilio: Josadac fue llevado cautivo por Nabucodonosor (1 Cr 5:41), y su hijo Josué se convirtió en el primer sumo sacerdote del Segundo Templo. Las cuatro apariciones aquí emplean la forma abreviada יוֹצָדָק que se encuentra en Esdras y Nehemías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3138', 'spa', 'Lluvia temprana, lluvias de otoño en Palestina (octubre-diciembre), opuesta a la lluvia tardía de primavera', 'Término para las lluvias otoñales que inauguran el año agrícola en la antigua Palestina, cayendo desde finales de octubre hasta principios de diciembre. Estas primeras lluvias ablandan la tierra para el arado y la siembra, en contraste con el מַלְקוֹשׁ (lluvias tardías de primavera) que maduran los cultivos antes de la cosecha. Presente en Deuteronomio 11:14, Jeremías 5:24 y Oseas 6:3, la lluvia temprana se convierte en una poderosa metáfora de la bendición y fidelidad de Dios. La nota textual en Oseas 6:3 sugiere que algunos manuscritos vocalizaron esta palabra como forma verbal en lugar de sustantivo, pero la imagen de la lluvia encaja perfectamente en el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3141', 'spa', 'Joram / Jehoram — ''YHWH es exaltado,'' nombre compartido por reyes de Israel y Juda. Nombre teoforico que significa ''YHWH es exaltado,'' que aparece tan', 'Joram / Jehoram — ''YHWH es exaltado,'' nombre compartido por reyes de Israel y Juda. Nombre teoforico que significa ''YHWH es exaltado,'' que aparece tanto en su forma completa יְהוֹרָם (Jehoram) como en las formas abreviadas יוֹרָם / יֹרָם (Joram/Yoram). Llevado de manera mas prominente por dos reyes contemporaneos: Joram hijo de Josafat, rey de Juda, y Joram hijo de Acab, rey de Israel — sus reinados superpuestos y nombre compartido crean algunos de los pasajes cronologicos mas confusos en Reyes (2 Re 1:17; 8:16). Otros portadores incluyen un sacerdote en los dias de Josafat (2 Cr 17:8) y un hijo de Tou rey de Hamat que trajo regalos a David (2 Sam 8:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3147', 'spa', 'Jotam -- nombre propio que significa ''YHWH es perfecto'', llevado por el hijo menor de Gedeón y un rey de Judá', 'Jotam -- nombre propio que significa ''YHWH es perfecto'', llevado por el hijo menor de Gedeón y un rey de Judá');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3148', 'spa', 'Más, en exceso, ventaja — adverbio y sustantivo de exceso, superioridad o surplus (Eclesiastés/Ester).', 'El sustantivo/adverbio יוֹתֵר (yoter), derivado de la raíz יתר (''quedar de sobra''), es un vocablo típico del hebreo tardío que se encuentra casi exclusivamente en Eclesiastés, donde constituye la herramienta favorita del Predicador para indagar qué ventaja tiene una cosa sobre otra. En su uso adverbial significa ''más'', ''en exceso'' o ''demasiado'', como cuando Qohélet advierte contra ser ''excesivamente justo'' (Ecl 7:16). En su acepción nominal denota ventaja o provecho: ''¿Qué ventaja tiene el sabio sobre el necio?'' (Ecl 6:8). En Ester 6:6 aparece con fuerza comparativa: Amán imagina que el rey desearía honrarlo ''más que'' a cualquier otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3156', 'spa', 'Yizrajías/Jezraías, nombre propio (ancestro isacarita, supervisor de cantores del templo)', 'Nombre propio hebreo que significa «Yahvé surgirá/resplandecerá». Aparece para dos personas distintas: un ancestro de la tribu de Isacar mencionado dos veces en 1 Crónicas 7:3, y un supervisor de los cantores del templo citado en Nehemías 12:42. Las variantes griegas (Ζαρεια, Ιεζρια, Ιεζερια) reflejan las fluctuaciones típicas al transliterar nombres teofóricos hebreos al griego. El significado del nombre conecta con la imagen de la luz divina que amanece o del poder de Dios que se levanta, un tema recurrente en la onomástica hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3157', 'spa', 'Jezreel — ''Dios siembra''; una ciudad en Isacar, un pueblo en Judá y un nombre personal simbólico (el hijo de Oseas)', 'Jezreel — ''Dios siembra''; una ciudad en Isacar, un pueblo en Judá y un nombre personal simbólico (el hijo de Oseas)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3158', 'spa', 'Jezreelita, adjetivo gentilicio que identifica a alguien procedente de Jezreel, aplicado a Nabot y a Ahinoam.', 'Adjetivo gentilicio que significa ''el de Jezreel'', empleado para identificar a dos figuras bíblicas destacadas. Siete de sus ocho apariciones designan a Nabot el jezreelita, propietario de una viña cuyo asesinato judicial orquestado por Jezabel se convirtió en un momento decisivo de confrontación profética contra el poder real (1 Re 21). La forma femenina identifica a Ahinoam la jezreelita, una de las primeras esposas de David (1 Sam 27:3; 30:5; 2 Sam 2:2; 3:2). Las formas masculina y femenina probablemente se refieren a ciudades distintas llamadas Jezreel: la de Nabot en la llanura de Esdrelón, y la de Ahinoam posiblemente en una localidad judía homónima.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3159', 'spa', 'Jezreelita; adjetivo gentilicio femenino que designa a una mujer oriunda de Jezreel', 'Forma gentilicia femenina de Jezreel, usada exclusivamente como epíteto de Ahinoam, una de las esposas de David. Cada aparición sigue la misma fórmula: ''Ahinoam la jezreelita'' (הַיִּזְרְעֵאלִית). Ella aparece por primera vez cuando David la toma como esposa durante su estancia entre los filisteos (1 Sam 27:3), lo acompaña durante la crisis de Siclag (1 Sam 30:5) y es nombrada en Hebrón (2 Sam 2:2; 3:2). El español ''la jezreelita'' conserva fielmente la construcción gentilicia, distinguiéndola de otras mujeres del mismo nombre personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3161', 'spa', 'Ser unido, unirse; concentrar (el corazón/los afectos) en devoción singular', 'Verbo que expresa unión o vinculación, y que aparece en tres contextos significativos. En Génesis 49:6, Jacob rehúsa que su honra se una a la asamblea violenta de Simeón y Leví. Isaías 14:20 declara que el tirano caído no será unido a otros reyes en la sepultura. Y de forma memorable, el Salmo 86:11 suplica: «unifica mi corazón para temer tu nombre», un ruego por una devoción íntegra frente a lealtades divididas. La forma Piel del Salmo intensifica el significado hacia «concentrar» o «enfocar», aunque algunas versiones antiguas (LXX, Peshitta, Vulgata) leen una raíz distinta que significa «que se alegre mi corazón».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3162a', 'spa', 'Juntos, a una, juntamente — adverbio que expresa comunidad de acción, lugar o tiempo', 'Juntos, a una, juntamente — adverbio que expresa comunidad de acción, lugar o tiempo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3162b', 'spa', 'Juntos, como uno solo — adverbio de acción comunal, proximidad espacial u ocurrencia simultánea. Yachdav es un adverbio hebreo que significa ''juntos,''', 'Juntos, como uno solo — adverbio de acción comunal, proximidad espacial u ocurrencia simultánea. Yachdav es un adverbio hebreo que significa ''juntos,'' derivado de la raíz y-ch-d que denota unidad. A lo largo de 97 apariciones describe a personas actuando en concierto, habitando en el mismo lugar o experimentando algo simultáneamente. Abraham e Isaac ''fueron juntos'' al Moriah (Gn 22:6, 8) — un detalle silenciosamente devastador que el narrador usa dos veces para subrayar el viaje compartido de padre e hijo hacia el sacrificio. Los Salmos lo emplean para la adoración comunal — ''engrandezcamos su nombre juntos'' (Sal 34:4) — y para el frágil ideal de hermanos que habitan en unidad (Sal 133:1, usando el relacionado yachad). Proféticamente puede marcar juicio colectivo: naciones reunidas juntas para la destrucción (Is 41:1; Jer 46:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3166', 'spa', 'Jahaziel — nombre propio que significa ''Dios ve'', llevado por guerreros, sacerdotes, levitas y un ancestro de la restauración.', 'Nombre teofórico hebreo (יַחֲזִיאֵל) que combina la raíz חזה (''ver, contemplar'') con אֵל (''Dios''), significando ''Dios ve'' o ''Dios contempla''. Al menos cinco individuos distintos llevan este nombre a lo largo de Crónicas y Esdras. La aparición más memorable es la del levita Jahaziel hijo de Zacarías, sobre quien vino el Espíritu del Señor durante la crisis de Josafat, profetizando que la batalla pertenecía a Dios, no a Judá (2 Chr 20:14). Otros incluyen un guerrero benjaminita entre los combatientes ambidiestros de David (1 Chr 12:5), un sacerdote designado para tocar las trompetas ante el arca (1 Chr 16:6) y levitas en la organización del templo de David (1 Chr 23:19; 24:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3168', 'spa', 'Ezequiel, nombre propio (célebre profeta del exilio, sacerdote del turno 19)', 'Nombre propio que significa «Dios fortalece», llevado de forma más célebre por el sacerdote-profeta Ezequiel hijo de Buzi, quien profetizó durante el exilio babilónico (Ezequiel 1:3; 24:24). El nombre también aparece en 1 Crónicas 24:16 para un sacerdote asignado al turno 19 (o 20, según algunos manuscritos griegos) en la organización del servicio del templo establecida por David. La forma griega Ιεζεκιηλ se convirtió en la forma estándar en la tradición cristiana. El elemento teofórico אֵל (Dios) combinado con חָזַק (fortalecer) produce un nombre que encarna el fortalecimiento divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3171', 'spa', 'Jehiel — nombre propio que significa ''que Dios viva'', portado por varios levitas, oficiales y líderes en Crónicas y Esdras', 'Nombre teofórico construido a partir de la oración ''que El viva'' (יְחִיאֵל), Jehiel aparece a lo largo de los libros históricos tardíos como un marcador recurrente de piedad levítica. Entre sus portadores más notables se encuentran uno de los músicos principales de David, designado para la procesión del arca (1 Cr 15:18, 20; 16:5), un jefe de los levitas encargado de los tesoros del templo (1 Cr 23:8; 29:8) y un tutor de los propios hijos de David (1 Cr 27:32). El nombre resurge en los reinados de Ezequías y Josías entre supervisores del templo, y de nuevo en la compañía de exiliados que regresaron con Esdras. Que tantos individuos sin parentesco compartan este nombre atestigua su popularidad como petición de vitalidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3173', 'spa', 'Único, singular, solitario; describe a un hijo único, la vida preciosa e irremplazable, o una persona sola y desamparada', 'יָחִיד conlleva un peso de singularidad. Su fuerza primaria es ''el único'': el ''hijo único'' Isaac de Abraham (Gn 22:2, 12, 16), donde el peso de la palabra intensifica el sacrificio de manera inconmensurable. El árabe wahid y el arameo yechidai comparten esta misma raíz semántica. En los Salmos, la forma femenina יְחִידָתִי se convierte en un nombre poético para la propia vida del salmista — ''mi única'', el ser singular e irremplazable amenazado por enemigos (Sal 22:20, 35:17). Y en los Salmos 25:16 y 68:6, יָחִיד se desplaza para describir al solitario y aislado, aquellos a quienes Dios integra en comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3176', 'spa', 'Esperar, tener esperanza; poner la confianza expectante en Dios o aguardar un resultado con anticipación', 'Esperar, tener esperanza; poner la confianza expectante en Dios o aguardar un resultado con anticipación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3179', 'spa', 'Estar en celo, aparearse (animales); calentarse, acalorarse (personas/cosas); (Piel) concebir un hijo', 'Una raíz cuyo significado irradia desde la sensación básica de calor. En su uso más frecuente, describe a animales entrando en celo: la estrategia de cría de Jacob con los rebaños de Labán depende de cuándo los animales ''se encendían en celo'' junto a los abrevaderos (Gn 30:38-41; 31:10). La misma raíz se aplica al calor físico ordinario: el anciano rey David no podía ''calentarse'' (1 Re 1:1), y dos que se acuestan juntos ''tendrán calor'' (Ec 4:11). Una única ocurrencia en Piel en el Salmo 51:5 eleva el significado a la concepción humana: ''en pecado me concibió mi madre'', una transferencia del celo animal al misterio teológico de la generación humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3182', 'spa', 'Descalzo; sin sandalias, como señal de duelo, humillación o cautiverio', 'Adjetivo que describe el estado de estar sin calzado, con un fuerte peso simbólico en el antiguo Israel. Andar descalzo significaba duelo, humillación o representación profética. David subió al Monte de los Olivos descalzo y llorando durante la revuelta de Absalón (2 Sam 15:30). Isaías caminó descalzo durante tres años como señal profética contra Egipto y Cus (Is 20:2-4). En Jeremías 2:25, la imagen se desplaza al sustantivo abstracto ''desnudez del pie'' — detén tu pie de andar descalzo — exhortando metafóricamente a Israel a dejar de correr tras dioses ajenos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3187', 'spa', 'Inscribirse o ser inscrito por genealogia; el registro genealogico mismo. Verbo denominativo en Hitpael de יָחַשׂ (genealogia), este verbo captura la ', 'Inscribirse o ser inscrito por genealogia; el registro genealogico mismo. Verbo denominativo en Hitpael de יָחַשׂ (genealogia), este verbo captura la practica israelita distintiva de rastrear y registrar el linaje ancestral. Funciona tanto verbalmente — registrarse o ser contado segun la linea familiar — como nominalmente, donde el infinitivo constructo sirve como sustantivo que significa ''la inscripcion genealogica'' o ''el registro.'' Se encuentra casi exclusivamente en Cronicas, Esdras y Nehemias, reflejando la urgente preocupacion de la comunidad postexilica por establecer una identidad israelita legitima.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3189', 'spa', 'Yajat — nombre propio masculino portado por un nieto de Judá y varios levitas, posiblemente significa ''él (Dios) arrebatará''.', 'Yajat es un nombre propio masculino que aparece en las genealogías de Crónicas, portado por al menos cinco individuos distintos. Uno es nieto de Judá a través de Sobal (1 Cr 4:2), mientras que los demás son levitas que sirvieron en diversas funciones a lo largo de la historia del culto israelita (1 Cr 6:5; 23:10; 24:22; 2 Cr 34:12). El nombre probablemente deriva de una raíz que significa ''él arrebatará'', sugiriendo rescate o liberación divina. La LXX lo transcribe de varias formas como Ιεθ, Ιααθ e Ιναθ, lo cual refleja distintas tradiciones manuscritas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3190', 'spa', 'Ser bueno, agradar; hacer bien, tratar bien; alegrarse; enmendar, mejorar; tocar con destreza; adverbial: bien, cabalmente', 'Esta raiz expresa la bondad en estado, accion y emocion. En el Qal describe situaciones o acciones que son buenas o agradables (''fue bueno a sus ojos'') y el corazon que se alegra. El Hifil hace bien a alguien activamente, lo trata con bondad o enmienda y corrige una situacion. Un uso adverbial (''bien, cabalmente'') intensifica las acciones. Acepciones especializadas incluyen tocar musica con destreza y causar alegria o regocijo. El arabe distingue ''ser bueno'' (حَسُنَ) de ''hacer bien'' (أَحْسَنَ, Forma IV) y ''reformar'' (أَصْلَحَ, de otra raiz), confirmando el amplio arco semantico del hebreo, desde la bondad inherente hasta la beneficencia activa y la ejecucion diestra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3193', 'spa', 'Jotbata, estación en el desierto durante las peregrinaciones de Israel, ubicación desconocida', 'Topónimo que significa «lugar agradable», identificando uno de los campamentos israelitas durante el período del desierto. Aparece en Números 33:33-34 (fuente sacerdotal) y en Deuteronomio 10:7 como una estación en la travesía, aunque su ubicación exacta sigue siendo desconocida para los estudiosos modernos. La etimología del nombre sugiere que pudo haber sido un oasis o un lugar particularmente grato en el duro paisaje desértico. Las variaciones preposicionales en las glosas (de, en, a Jotbata) simplemente reflejan los distintos contextos narrativos en que se menciona el lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3195', 'spa', 'Yetur/Jetur, hijo de Ismael y nombre tribal; ancestros de los itureos en la región del Antilíbano', 'Nombre personal y tribal de uno de los «hijos» de Ismael registrados en Génesis 25:15 y 1 Crónicas 1:31, quien dio nombre a una tribu. En 1 Crónicas 5:19 esta tribu aparece entre los pueblos contra los que guerrearon Rubén, Gad y la media tribu de Manasés. Las fuentes clásicas los identifican con los itureos (griego Ἰτουραῖοι), conocidos por Estrabón y Josefo, quienes habitaban la región del Antilíbano. Lucas 3:1 menciona «la región de Iturea y Traconítide» en tiempos de Jesús, mostrando la perdurable presencia de este pueblo. El nombre podría estar vinculado etimológicamente con la palabra para «campamento» (טִירָה).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3196', 'spa', 'Vino -- bebida fermentada de uva, empleada en la vida cotidiana, las ofrendas culticas, la celebracion festiva y las advertencias contra el exceso', 'יַיִן es la palabra hebrea estandar para el vino, con 141 apariciones en todos los generos de la Escritura. Entra en la narrativa ya con la vina de Noe (Gn 9:21) e impregna la vida diaria: Melquisedec trae pan y vino a Abram (Gn 14:18), acompana la provision y la hospitalidad (Jue 19:19; 2 S 16:2), y los profetas lo prometen como signo de bendicion restaurada (Am 9:14; Os 14:8). Sin embargo, la misma palabra conlleva advertencias sobrias: el exceso conduce a la verguenza (Gn 9:21), a la burla (Pr 20:1) y a la ruina (Is 5:11-12). Los cognados en las lenguas semiticas (etiope wayn, acadio inu) confirman un vocabulario viticola antiguo y compartido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3198', 'spa', 'Reprender, reprochar; argumentar o defender una causa; decidir, juzgar, arbitrar; disciplinar; designar, señalar. Verbo predominantemente en Hifil que', 'Reprender, reprochar; argumentar o defender una causa; decidir, juzgar, arbitrar; disciplinar; designar, señalar. Verbo predominantemente en Hifil que abarca desde la argumentación judicial hasta la corrección paternal. En su esencia, יָכַח implica la confrontación autoritativa del mal: ya sea un profeta reprendiendo el pecado (Lv 19:17), Dios disciplinando a quienes ama (Pr 3:12), o un juez arbitrando entre partes en disputa (Is 2:4). La dimensión forense-retórica emerge con fuerza en Job, donde el sufriente exige ''argumentar su causa'' ante Dios (Job 13:3, 15). Una extensión semántica rara pero notable alcanza el ámbito del nombramiento divino, como cuando Dios ''designa'' a Rebeca como esposa de Isaac (Gn 24:14, 44).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3199', 'spa', 'Jaquín — ''él establecerá''; nombre de un clan simeonita y del pilar derecho ante el templo de Salomón.', 'Jaquín (יָכִין) es un nombre teofórico que significa ''él establecerá'', asociado tanto a personas como a un célebre elemento arquitectónico. Como nombre personal, pertenece a un hijo de Simeón mencionado en las genealogías de Génesis 46:10, Éxodo 6:15 y Números 26:12. De modo más notable, es el nombre asignado al pilar de bronce derecho situado ante el templo de Salomón (1 Re 7:21; 2 Cr 3:17), emparejado con Boaz a la izquierda. Juntos, los nombres de ambos pilares podrían formar una declaración: ''Él establecerá… con fuerza''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3201', 'spa', 'Poder, ser capaz; prevalecer o vencer; soportar o resistir adversidades', 'Verbo modal fundamental del hebreo que expresa capacidad, competencia y poder. Su funcion mas basica es ''poder'' o ''ser capaz'': la habilidad de realizar una accion, sea fisica, moral o circunstancial. Pero esta raiz se extiende notablemente: Jacob lucha con el angel y ''prevalece'' (Gn 32:28), y Ester pregunta como ''podra soportar'' ver destruido a su pueblo (Est 8:6). Lo que el hebreo expresa con una sola raiz versatil, otras lenguas deben repartirlo entre multiples campos semanticos: el suajili usa -shinda (''vencer'') para prevalecer, y el hindi sahna (''aguantar'') para soportar, confirmando que capacidad, victoria y resistencia son acepciones genuinamente distintas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3202', 'spa', 'Verbo arameo: poder, tener capacidad o facultad; raramente, prevalecer contra o vencer', 'El cognado arameo del hebreo יָכֹל, este verbo expresa capacidad y facultad a lo largo de las secciones arameas de Daniel. Es la palabra empleada para indagar si alguien ''puede'' interpretar el sueño del rey (Dan 2:10, 27), para afirmar que Dios ''puede'' librar del horno (Dan 3:17) y para declarar que ningún dios ''puede'' revocar sus decretos (Dan 3:29). En su único uso divergente (Dan 7:21), adquiere un matiz combativo: el cuerno pequeño ''prevaleció contra'' los santos, pasando de la capacidad a la conquista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3203', 'spa', 'Jecolías/Yecolyahu, madre del rey Azarías (Uzías) de Judá', 'Nombre propio de la madre de Azarías (también llamado Uzías), que aparece en las fórmulas analísticas reales. Se escribe יכליהו en 2 Reyes 15:2 y יכליה en 2 Crónicas 26:3 (Qeré; el Ketiv lee יכיליה), mostrando la variación típica en las terminaciones de nombres teofóricos. El nombre significa «Yahvé ha podido» o «Yahvé es capaz», construido sobre la raíz יכל (poder, prevalecer). Las versiones griegas varían (Χαλεια, Χααια, Ιεχελια), reflejando las dificultades de transliteración. Como reina madre, habría desempeñado funciones ceremoniales y posiblemente políticas importantes en el Judá del siglo VIII a.C.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3204', 'spa', 'Jeconías (Yekhonyah/Yekhanyahu), penúltimo rey de Judá exiliado a Babilonia, también llamado Joaquín', 'Jeconías es uno de los varios nombres del desafortunado rey de Judá que reinó brevemente antes de ser deportado a Babilonia en el 597 a.C. Las variantes ortográficas — Yekhonyah, Yekhanyahu y la abreviatura Konyahu — significan todas ''YHWH establece'', aunque el nombre resulta profundamente irónico dada la pérdida del trono y la tierra por parte del rey. Jeremías emplea el diminutivo Konyahu en su oráculo más severo contra este monarca (Jer 22:24, 28), mientras que las formas completas aparecen en la genealogía del Cronista (1 Cr 3:16-17) y en Ester 2:6, vinculando el linaje de Mardoqueo con este rey exiliado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3205', 'spa', 'Parir, dar a luz, engendrar o nacer; abarca el alumbramiento materno, la generacion paterna, el nacimiento pasivo y la parteria', 'En el corazon de cada genealogia y relato de nacimiento biblico se encuentra יָלַד, verbo cuyo arco semantico traza la totalidad de la generacion humana. Una madre ''da a luz'' (Gn 4:1), un padre ''engendra'' (Gn 4:18) y un hijo ''nace'' (Gn 4:26), todo desde la misma raiz. La conjugacion Piel produce una acepcion profesional enteramente distinta: ''ejercer de partera'', confirmada por el paso del arabe a la raiz no emparentada q-b-l. Desde las cadenas genealogicas del Genesis hasta la promesa mesianica de Isaias 9:6, יָלַד transporta el drama biblico del linaje, la herencia y el proposito divino a traves del nacimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3206', 'spa', 'Niño, muchacho, joven: un ser humano joven desde la infancia hasta la adolescencia; raramente, la cría de animales. Término directo para una persona j', 'Niño, muchacho, joven: un ser humano joven desde la infancia hasta la adolescencia; raramente, la cría de animales. Término directo para una persona joven que abarca desde la infancia hasta la adolescencia. Aparece con especial densidad en las narrativas patriarcales: el hijo de Agar en el desierto (Gn 21:14-16), los hijos de Jacob al encontrarse con Esaú (Gn 33:1-14) y el bebé Moisés escondido entre los juncos (Éx 2:3-10). A diferencia de בֵּן (''hijo''), que enfatiza el linaje, יֶלֶד destaca la edad y la vulnerabilidad. El plural יְלָדִים a menudo significa simplemente ''niños'' o ''pequeños''. En un puñado de pasajes poéticos, la palabra se extiende a las crías de animales: las crías de las bestias salvajes que claman a Dios por alimento (Job 38:41) o que descansan pacíficamente junto a la vaca (Is 11:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3207', 'spa', 'niña, muchacha, doncella en edad casadera', 'Sustantivo femenino que designa a una niña o muchacha joven, especialmente en edad casadera. Aparece tres veces: describiendo a Dina tras su violación (Génesis 34:4), emparejada con «niño» (יֶלֶד) en Joel 3:3, donde los enemigos venden niños a prostitutas y niñas por vino, y en Zacarías 8:5, en una visión de la Jerusalén restaurada donde niños y niñas juegan seguros en las calles. El término capta la ternura de la juventud, tanto en la tragedia (Dina, los niños esclavizados de Joel) como en la esperanza (el futuro pacífico de Zacarías). A diferencia de נַעֲרָה, que puede implicar servidumbre, יַלְדָּה enfatiza la juventud y el potencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3208', 'spa', 'niñez, juventud, mocedad; tiempo de vigor y vitalidad', 'Sustantivo abstracto que designa el período de la juventud o la niñez, y que aparece exclusivamente en la literatura sapiencial y poética. Eclesiastés lo usa dos veces: en 11:9, exhortando al joven a alegrarse en su juventud sin olvidar el juicio venidero, y en 11:10, donde se empareja con «la aurora de la vida» (שַׁחֲרוּת). El Salmo 110:3 contiene la difícil expresión «el rocío de tu juventud», que podría referirse a guerreros jóvenes o a la frescura del vigor juvenil. El término capta no solo la edad cronológica, sino la vitalidad, el potencial y la transitoriedad de los primeros años de vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3209', 'spa', 'nacido, el que ha nacido; usado para hijos en un lugar o circunstancia particular', 'Adjetivo derivado del verbo יָלַד (''dar a luz, parir''), que describe a alguien que ha nacido, especialmente en un lugar o situación específica. Aparece con el artículo para identificar un grupo definido: ''el niño que naciere'' (Éx 1:22), ''el pueblo nacido en el desierto'' (Jos 5:5), hijos ''nacidos en Jerusalén'' (2 S 5:14) o el hijo ''que te ha nacido'' (2 S 12:14). Cada contexto subraya las circunstancias del nacimiento como determinantes para lo que sigue.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3211', 'spa', 'Nacido en la casa; nativo, descendiente de un linaje particular', 'Adjetivo usado exclusivamente en forma constructa, que significa ''nacido de'' o ''nativo de'' una casa o linaje particular. En las narrativas patriarcales describe a esclavos nacidos dentro del hogar de Abraham, distinguiéndolos de los comprados con dinero (Gn 14:14; 17:12-13, 23, 27; Lv 22:11). En otros contextos identifica a descendientes de grupos específicos: los hijos de los gigantes refaítas en las guerras filisteas (2 S 21:16, 18; 1 Cr 20:4) y los hijos de Anac en la narrativa de la conquista (Nm 13:22, 28; Jos 15:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3212', 'spa', 'ir, caminar, partir; figuradamente: andar en un modo de vida; idiomáticamente: ¡ven!; Hifil: guiar, conducir', 'Halak es uno de los verbos más frecuentes de la Biblia hebrea y de los más versátiles semánticamente. En su núcleo significa simplemente ''ir'' —el verbo de locomoción no marcado que cubre desde Abraham partiendo hacia Canaán (Gn 12:4) hasta Elías caminando cuarenta días hacia Horeb. Pero su alcance figurado es enorme: ''andar en los caminos del SEÑOR'' es la metáfora bíblica por excelencia de la obediencia fiel, y ''andar en los estatutos de las naciones'' es su antónimo. El imperativo לֵךְ/לְכוּ funciona frecuentemente no como ''¡vete!'' sino como ''¡ven!'' o ''¡vamos!'' —una invitación a la acción conjunta. El Hifil causativo añade agencia: Dios ''condujo'' a Israel por el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3213', 'spa', 'Aullar, gemir — clamar en fuerte lamentación, expresando intenso dolor, angustia o duelo profético', 'Aullar, gemir — clamar en fuerte lamentación, expresando intenso dolor, angustia o duelo profético');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3215', 'spa', 'Aullido, gemido; grito fuerte de angustia o lamentación colectiva', 'Sustantivo femenino que denota un lamento fuerte y angustiado — el tipo de clamor colectivo que acompaña a la catástrofe. Isaías 15:8 describe la devastación de Moab con aullidos que se extienden de una ciudad a otra. Jeremías lo emplea para el gemido de los líderes (metafóricamente ''pastores'') que enfrentan el juicio divino (Jer 25:36). Sofonías lo empareja con el grito desde la Puerta del Pescado en el día del SEÑOR (Sof 1:10). En Zacarías 11:3, es el aullido de pastores cuya gloria ha sido arruinada. El español ''aullido'' evoca la cualidad visceral y casi animal de esta lamentación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3218', 'spa', 'Especie o fase de langosta, usado colectivamente para enjambres devastadores que devoran cosechas y simbolizan multitudes abrumadoras.', 'El sustantivo יֶלֶק designa un tipo particular de langosta — posiblemente una fase de desarrollo como la ''langosta saltona'' o ''langosta rastrera'' — siempre empleado de forma colectiva. La célebre secuencia de langostas de Joel lo enumera junto a גָּזָם, אַרְבֶּה y חָסִיל como oleadas sucesivas de destrucción (Jl 1:4; 2:25), mientras que el Salmo 105:34 evoca la plaga de Egipto. Nahúm lo utiliza en vívidas comparaciones: los mercaderes se multiplican como יֶלֶק, pero se dispersan y desaparecen al salir el sol (Nah 3:15-16). La dificultad perenne de precisar la identificación entomológica exacta de los términos hebreos para insectos se refleja en las variadas traducciones entre idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3220', 'spa', 'Mar o gran masa de agua; la dirección ''oeste'' (por la orientación mediterránea de Israel); o primer elemento de topónimos marítimos.', 'Yam es la palabra hebrea para mar, con una notable triple función: cuerpo de agua literal, punto cardinal y componente de nombres geográficos. Como cuerpo de agua designa el Mediterráneo, el mar Rojo (yam suf), el mar Muerto y el gran ''mar'' de bronce del templo de Salomón (1 R 7:23). Dado que el Mediterráneo queda al oeste de Israel, yam se convirtió en el término estándar para ''hacia el oeste'', un sentido direccional. En cadenas constructas como yam suf o yam kinneret funciona como primer elemento de nombres propios geográficos, patrón visible en todas las lenguas receptoras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3225', 'spa', 'Mano derecha, lado derecho o sur; indica dirección espacial, la mano como instrumento de poder y el punto cardinal meridional.', 'Yamin es uno de esos sustantivos hebreos cuyo campo semántico revela toda una cosmovisión. En su sentido más concreto, es simplemente la mano derecha: la mano de la fuerza, la destreza y la bendición (Gn 48:13-14). De ahí se extiende al lado derecho como dirección espacial (''no te desvíes ni a la derecha ni a la izquierda'') y, dado que los israelitas se orientaban mirando al este, la mano derecha señalaba al sur, lo que otorga a yamin su sentido geográfico. El español distingue significativamente entre diestra (la poderosa mano derecha, a menudo de Dios) y derecha (el lado direccional), reflejando la riqueza teológica de la palabra, central en la expectativa mesiánica (Sal 110:1) y en la alabanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3226', 'spa', 'Jamín — nombre propio que significa ''mano derecha'', llevado por un fundador de clan simeonita, un judíta y un levita en tiempos de Esdras.', 'Nombre propio hebreo (יָמִין) derivado del sustantivo común para ''mano derecha'' o ''sur'', con connotaciones de fuerza, favor y buena fortuna. Tres individuos distintos llevan este nombre. El más antiguo es un hijo de Simeón enumerado entre quienes descendieron a Egipto con Jacob (Gen 46:10; Exod 6:15), cuyos descendientes formaron el clan jaminita (Num 26:12). Un Jamín judíta aparece en la genealogía de Jerameel como hijo de Ram (1 Chr 2:27). El tercero es un levita o líder laico que ayudó a Esdras a explicar la Torá al pueblo congregado (Neh 8:7). Las formas con conjunción como ''y-Jamín'' reflejan las construcciones copulativas frecuentes en las listas genealógicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3227b', 'spa', 'benjaminita, miembro de la tribu de Benjamín (gentilicio derivado de Benjamín)', 'Adjetivo gentilicio que significa «benjaminita», denotando a alguien de la tribu de Benjamín. Es una forma abreviada de la expresión completa בֶּן־יְמִינִי (hijo de la diestra / de Benjamín). El término aparece en narraciones sobre el linaje y la tribu de Saúl: describiéndolo como «un hombre benjaminita» (1 Samuel 9:1), refiriéndose a la «tierra de los benjaminitas» (1 Samuel 9:4), y en la reprensión de David a sus hombres cuando pregunta si un benjaminita les daría campos y viñas (1 Samuel 22:7). Siendo Benjamín la tribu más pequeña de Israel (aparte de Leví), pero la que produjo al primer rey, la identidad benjaminita conllevaba tanto prestigio como emotividad tras la guerra civil tribal de Jueces 19-21.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3229', 'spa', 'Imla, padre del profeta Micaías que se opuso a los falsos profetas de Acab', 'Nombre personal que identifica al padre del profeta Micaías, quien se enfrentó célebremente a cuatrocientos profetas de la corte al predecir la muerte de Acab en Ramot de Galaad (1 R 22:8–9; 2 Cr 18:7–8). El nombre aparece solo en la fórmula ''Micaías hijo de Imla,'' que funciona como patronímico para distinguir a este Micaías de otros. La grafía alternante יִמְלָא en Crónicas conserva el mismo nombre con una ligera variación ortográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3231', 'spa', 'Ir a la derecha, girar hacia la derecha, usar la mano derecha', 'Verbo denominativo derivado de יָמִין (''mano derecha, sur''), empleado en Hifil con el sentido de ''ir a la derecha'' o ''usar la mano derecha.'' Aparece en contextos tanto espaciales como morales: Abram ofrece a Lot la opción de ir a la derecha o a la izquierda (Gn 13:9), Isaías advierte contra desviarse del camino verdadero (Is 30:21), y a la espada de Ezequiel se le ordena dirigirse a la derecha (Ez 21:16). En 1 Cr 12:2 describe a los guerreros benjamitas ambidextros, capaces de lanzar y disparar con ambas manos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3232', 'spa', 'Imna (Jimna); nombre propio que posiblemente significa ''buena fortuna'' o ''lado derecho''', 'Nombre propio posiblemente relacionado con el árabe yumn (''buena fortuna'') o yamnah (''lado derecho''), sugiriendo un nombre de buen augurio. Imna aparece principalmente como hijo de Aser en las genealogías patriarcales (Gn 46:17; 1 Cr 7:30), y sus descendientes forman el clan de los imnitas (Nm 26:44). Un segundo Imna sirve como levita bajo Ezequías, supervisando las ofrendas del templo (2 Cr 31:14). El inglés y el español transliteran consistentemente como ''Imnah/Imna'', mientras que el francés y el alemán a veces dejan el hebreo sin vocalizar en sus glosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3233', 'spa', 'Derecho/a (adj.) — relativo a la mano derecha o al lado derecho, usado para partes del cuerpo, elementos arquitectónicos y rituales', 'Derecho/a (adj.) — relativo a la mano derecha o al lado derecho, usado para partes del cuerpo, elementos arquitectónicos y rituales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3238', 'spa', 'Oprimir, agraviar o maltratar; tambien usado como participio con el significado de ''opresor.'' Yanah describe el acto de agraviar u oprimir a otra pers', 'Oprimir, agraviar o maltratar; tambien usado como participio con el significado de ''opresor.'' Yanah describe el acto de agraviar u oprimir a otra persona, particularmente en contextos de vulnerabilidad social y economica. La Tora lo usa enfaticamente en las leyes que protegen al extranjero: ''No oprimiras al extranjero'' (Ex 22:21; Lv 19:33), y en la equidad comercial: ''No os agraviareis unos a otros'' en los tratos comerciales (Lv 25:14, 17). En los profetas, la forma participial se convierte en sustantivo — ''el opresor'' — nombrando al agente de la injusticia: la ciudad opresora en Sofonias 3:1, la espada del opresor en Jeremias 46:16 y 50:16, y la promesa de Dios de hacer que los opresores de Israel devoren su propia carne (Is 49:26).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3240', 'spa', 'Colocar, depositar, dejar o dar reposo; en Hifil, depositar en un lugar, abandonar, permitir o establecer; en Hofal, ser colocado o dejado. Derivado d', 'Colocar, depositar, dejar o dar reposo; en Hifil, depositar en un lugar, abandonar, permitir o establecer; en Hofal, ser colocado o dejado. Derivado de la raíz נוח (''reposar''), este verbo en su forma causativa Hifil desarrolla un arco semántico sorprendentemente amplio: desde el acto físico concreto de colocar un objeto en algún lugar, pasando por el acto relacional de dejar o abandonar, hasta conceder reposo o dar permiso. Dios ''coloca'' a Adán en el Jardín (Gn 2:15), la esposa de José ''deja'' su vestidura junto a ella (Gn 39:16), y el SEÑOR promete ''establecer'' a Israel en su propia tierra (Is 14:1). La unidad del verbo reside en una lógica espacial compartida: ya sea depositar, dejar atrás o permitir que algo permanezca, algo llega a reposar en algún lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3243', 'spa', 'Mamar, amamantar; como participio: lactante o nodriza; causativo: dar de mamar, amamantar a un niño', 'Mamar, amamantar; como participio: lactante o nodriza; causativo: dar de mamar, amamantar a un niño');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3244', 'spa', 'búho (gran búho, búho real), ave impura que habita ruinas desiertas', 'Nombre de un ave, probablemente una especie de búho, quizá el gran búho o el búho real egipcio según la mayoría de los eruditos. Aparece entre las aves impuras en Levítico 11:17 y Deuteronomio 14:16, y también en Isaías 34:11 como habitante de lugares desolados, dentro de la visión profética de la destrucción de Edom. Su etimología podría relacionarse con sonidos estridentes (evocando el llamado del búho) o con el crepúsculo (נֶשֶׁף), dado que los búhos son cazadores crepusculares. Aunque la Septuaginta y la Vulgata sugieren ''ibis'', la mayoría de los estudiosos modernos favorecen una especie de búho por el hábitat desértico y otras pistas contextuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3245', 'spa', 'Fundar, poner cimiento, establecer; Nifal: ser fundado; también: consultarse, conspirar', 'Fundar, poner cimiento, establecer; Nifal: ser fundado; también: consultarse, conspirar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3247', 'spa', 'Fundamento, base — la parte estructural inferior de un edificio, altar o muro; también se usa en sentido figurado', 'Fundamento, base — la parte estructural inferior de un edificio, altar o muro; también se usa en sentido figurado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3254', 'spa', 'Añadir, aumentar; continuar, volver a hacer; en Nifal: ser añadido, unirse a.', 'Uno de los verbos más versátiles del hebreo, yasaf cumple doble función: como término cuantitativo (''añadir más'', ''aumentar'') y como auxiliar de repetición (''volver a hacer'', ''continuar''). Cuando Dios promete no volver a inundar la tierra (Gn 8:21), yasaf tiene fuerza de ''no repetir''. Cuando Levítico prescribe añadir un quinto al pago de restitución (Lv 5:16), la misma raíz indica incremento aritmético. El uso auxiliar, sin paralelo en muchas lenguas, a menudo requiere perífrasis. El Nifal pasivo completa el paradigma con sentidos de ser reunido o incorporado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3256', 'spa', 'Disciplinar, castigar, instruir o amonestar; corrección administrada por Dios o una autoridad humana para producir obediencia y sabiduría.', 'Disciplinar, castigar, instruir o amonestar; corrección administrada por Dios o una autoridad humana para producir obediencia y sabiduría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3257', 'spa', 'Palas o recogedores de ceniza usados como utensilios cúlticos para retirar las cenizas del altar de holocaustos en el tabernáculo y el templo.', 'El sustantivo יָעִים se refiere a las palas o recogedores de ceniza que formaban parte del inventario estándar de utensilios del altar en el culto israelita. Todas sus apariciones se encuentran en listas de equipamiento — nunca en acción narrativa — catalogando los implementos de bronce del tabernáculo (Éx 27:3; 38:3; Nm 4:14) o del templo de Salomón (1 Re 7:40, 45). Los mismos objetos se mencionan entre los que los babilonios se llevaron al exilio (2 Re 25:14; Jer 52:18). El sentido básico es el de una herramienta plana para recoger, consistente con la traducción habitual de ''palas'' en español y ''Schaufeln'' en alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3258', 'spa', 'Jabes, hombre de oración y ciudad en Judá cercana a Belén', 'Nombre propio que designa tanto a una persona como a un lugar en la tribu de Judá. El hombre Jabes es célebre por su breve pero ferviente oración en 1 Cr 4:9-10, donde el texto vincula su nombre con la palabra para dolor (עֹצֶב), señalando que su madre lo dio a luz con aflicción. A pesar de este origen desfavorable, Jabes invocó a Dios para que lo bendijera y ensanchara su territorio, y Dios le concedió su petición. El lugar Jabes (1 Cr 2:55) parece ser una ciudad en Judá cercana a Belén donde se asentaron familias de escribas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3259', 'spa', 'Designar, señalar o reunirse por acuerdo; abarca congregarse, encontrarse en un lugar fijado, nombrar personas, convocar a juicio y conspirar juntos', 'Designar, señalar o reunirse por acuerdo; abarca congregarse, encontrarse en un lugar fijado, nombrar personas, convocar a juicio y conspirar juntos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3266', 'spa', 'Yeush (יְעוּשׁ) — nombre propio de varios personajes bíblicos, principalmente un jefe edomita descendiente de Esaú', 'El nombre יְעוּשׁ (Yeush), que posiblemente significa ''él viene a socorrer'' o ''que [Dios] ayude'', pertenece a por lo menos cinco individuos en la Biblia hebrea. El más prominente es Yeush hijo de Esaú con su esposa Oholibama, quien llegó a ser jefe de clan edomita (Gn 36:5, 14, 18; 1 Cr 1:35). Un Yeush benjaminita aparece en la genealogía de Saúl (1 Cr 7:10; 8:39), y otro es hijo de Roboam (2 Cr 11:19). Un Yeush levita figura entre los hijos de Simei (1 Cr 23:10-11). La recurrencia de este nombre a través de fronteras tribales —edomita, benjaminita, judahita, levítica— ilustra el uso extendido de patrones onomásticos teofóricos en las culturas semíticas occidentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3270', 'spa', 'Jazer — ciudad transjordana en Galaad asignada a la tribu de Gad', 'Nombre de lugar para una ciudad al este del Jordán en la meseta de Galaad, originalmente conquistada de los amorreos (Nm 21:32) y luego asignada a Gad (Nm 32:1, 35; Jos 13:25). Sirvió como ciudad levítica (Jos 21:39; 1 Cr 6:66) y centro administrativo (1 Cr 26:31). Los profetas asocian a Jazer con sus fértiles viñedos, lamentando su devastación junto con los de Moab (Is 16:8-9; Jer 48:32). La ruta del censo de David también pasó por Jazer (2 S 24:5), confirmando su importancia regional en la Transjordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3273', 'spa', 'Jeiel — nombre propio hebreo portado por múltiples levitas, guerreros y jefes de clan en Crónicas y Esdras', 'Jeiel — nombre propio hebreo portado por múltiples levitas, guerreros y jefes de clan en Crónicas y Esdras');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3276', 'spa', 'Aprovechar, beneficiar o servir de algo; ser útil — casi siempre negado, exponiendo la futilidad de los ídolos o la riqueza', 'Aprovechar, beneficiar o servir de algo; ser útil — casi siempre negado, exponiendo la futilidad de los ídolos o la riqueza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3277', 'spa', 'cabra montés, íbice, cabra salvaje que habita riscos rocosos', 'La cabra montés o íbice, un caprino salvaje adaptado a terrenos rocosos y montañosos. El término aparece en tres contextos poéticos que celebran el cuidado de Dios por las criaturas silvestres: el Salmo 104:18 describe las altas montañas como refugio de las cabras monteses (junto con los tejones de roca); Job 39:1 pregunta si Job sabe cuándo paren las cabras monteses de las peñas (en paralelo con las ciervas); y 1 Samuel 24:2 menciona las ''Peñas de las Cabras Monteses'', un topónimo en el desierto de Judea donde David se escondía de Saúl. El íbice, con su extraordinaria habilidad trepadora y sus majestuosos cuernos curvos, simbolizaba la libertad y la provisión divina en el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3278', 'spa', 'Jael — esposa de Heber el ceneo, célebre por matar al general cananeo Sísara con una estaca de tienda (Jueces 4–5).', 'Nombre propio femenino hebreo (יָעֵל) que probablemente significa ''cabra montés'' o ''íbice'', llevado por una de las mujeres más destacadas de la Biblia hebrea. Jael, esposa de Heber el ceneo, ofreció hospitalidad al general cananeo Sísara tras la derrota de su ejército, y luego le clavó una estaca de tienda en la sien mientras dormía (Jue 4:17–22). El cántico de Débora la celebra con la bendición enfática: ''Bendita sea entre las mujeres Jael'' (Jue 5:24). El nombre podría aparecer también en Jueces 5:6 como referencia a un personaje anterior, aunque algunos eruditos lo interpretan como la misma Jael en otro contexto. Notablemente uniforme entre idiomas, se traduce simplemente como ''Yael''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3281', 'spa', 'Yalam, hijo de Esaú y Oholibama, jefe edomita', 'Yalam aparece en las genealogías como uno de los hijos de Esaú con su esposa Oholibama. Incluido entre los jefes de Edom, representa una de las líneas familiares descendientes de Isaac a través de Esaú en lugar de Jacob. Su nombre figura tanto en el relato de Génesis sobre los descendientes de Esaú como en la genealogía paralela conservada en Crónicas, lo que confirma su posición dentro de la estructura tribal edomita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3282', 'spa', 'Porque, por cuanto, ya que — conjunción causal que introduce el fundamento o razón, especialmente en oráculos proféticos de juicio.', 'Ya''an es una conjunción causal que aparece 99 veces, concentrada en gran medida en la literatura profética, donde introduce los fundamentos del juicio divino. Su patrón más característico es la construcción ya''an...laken (''por cuanto...por tanto''): el profeta expone la ofensa con ya''an y luego anuncia la consecuencia con laken. Solo Ezequiel representa casi la mitad de las apariciones, empleándola para acusar a naciones e individuos por igual: ''por cuanto dijiste contra el templo del SEÑOR'' (Ez 25:3), ''por cuanto Tiro dijo contra Jerusalén'' (26:2). Fuera de la profecía, aparece en textos clave de alianza como Génesis 22:16 (''por cuanto has hecho esto'') y Números 20:12 (''por cuanto no me creísteis'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3284', 'spa', 'Avestruz; ave grande no voladora asociada en las Escrituras con el duelo, la desolación y la impureza ritual.', 'Este sustantivo femenino designa al avestruz, y aparece exclusivamente en las locuciones compuestas bat hayya''anah (''hija del avestruz'') y benot ya''anah (''hijas del avestruz''). El avestruz funciona como un poderoso símbolo literario: su inquietante graznido lo convierte en símil del lamento en Miqueas 1:8, su preferencia por terrenos desolados marca ciudades arruinadas en Isaías 13:21 y 34:13, y su hábitat salvaje lo hace compañero de chacales en Job 30:29. Levítico 11:16 y Deuteronomio 14:15 lo incluyen entre las aves impuras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3286', 'spa', 'Cansarse, desfallecer por agotamiento o carencia; también (Hofal) ser hecho volar velozmente', 'Ante todo, un verbo de agotamiento humano: el cansancio profundo que alcanza incluso a los jóvenes y fuertes. Isaías 40:28-31 construye su famoso crescendo en torno a esta palabra: YHWH no se cansa (yi''af), los jóvenes se cansan y tropiezan, pero los que esperan en YHWH levantarán alas como las águilas. La ironía resulta exquisita cuando el participio Hofal מֻעָף aparece en Daniel 9:21, donde Gabriel llega ''hecho volar velozmente'': la misma raíz que en otros contextos significa ''estar exhausto'' se transforma aquí en velocidad sobrenatural. El español capta el sentido primario con ''se cansarán'' y el sentido de vuelo con ''volando'', marcando con claridad el salto semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3287', 'spa', 'cansado, agotado, exhausto (por esfuerzo físico o falta de alimento y agua)', 'Adjetivo que describe agotamiento físico o espiritual, utilizado como sustantivo en sus tres apariciones bíblicas. En 2 Samuel 16:2, las provisiones de David son ''para los cansados'' que carecen de bebida en el desierto. Isaías 40:29 promete que Dios da fuerza al que no tiene vigor, en paralelo con ''el cansado''. Isaías 50:4 habla de saber sostener al cansado con una palabra oportuna. El término no describe simple cansancio, sino un agotamiento genuino — ya sea por hambre, sed o las cargas de la vida — lo cual hace que el sustento divino sea aún más necesario y precioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3289', 'spa', 'Aconsejar, dar consejo, consultar juntos; como participio, un consejero; también determinar, planificar o decretar, especialmente del decreto soberano', 'Aconsejar, dar consejo, consultar juntos; como participio, un consejero; también determinar, planificar o decretar, especialmente del decreto soberano de Dios. יָעַץ abarca todo el arco de la deliberación: desde el acto privado de planificar en el corazón, pasando por buscar y dar consejo entre personas, hasta la gran afirmación teológica de que Dios mismo ''determina'' y nadie puede frustrarlo. El alcance de la palabra se ve en sus contextos más célebres: Jetro aconsejando a Moisés sobre la gobernanza (Éx 18:19), Ahitofel cuyo consejo ''era como si se consultara el oráculo de Dios'' (2 S 16:23), y el título mesiánico de Isaías יוֹעֵץ (''Consejero Admirable'', Is 9:6). El participio יוֹעֵץ llegó a ser prácticamente un título político en la corte de Israel, junto a los oficiales del rey y los comandantes militares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3290', 'spa', 'Jacob — el patriarca (hijo de Isaac), renombrado después Israel, y por extensión la nación descendiente de él.', 'Ya''aqov (Jacob) es uno de los nombres más prominentes de la Biblia, con 349 apariciones tanto como nombre personal como designación nacional. La etimología popular de Génesis 25:26 lo vincula con ''aqev (''talón''), pues Jacob asió el talón de Esaú al nacer, y Génesis 27:36 juega con ''aqav (''suplantar''). Registros egipcios mencionan un lugar llamado Ya''qub-''el, lo que sugiere que el nombre pudo contener originalmente un elemento divino. Como patriarca, Jacob recibió el nombre de Israel tras luchar con Dios (Gn 32:28), y a partir de entonces ambos nombres alternan como designación de sus descendientes y su nación, especialmente en la poesía profética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3293a', 'spa', 'Bosque, arboleda, espesura; una vez como nombre propio (Yaar) asociado con Quiriat-jearim. Designa un área boscosa, bosque o espesura densa: el terren', 'Bosque, arboleda, espesura; una vez como nombre propio (Yaar) asociado con Quiriat-jearim. Designa un área boscosa, bosque o espesura densa: el terreno silvestre e indómito que contrasta con la tierra cultivada en la imaginación hebrea. Bosques con nombre propio como el ''bosque del Líbano'' (1 R 7:2), el ''bosque de Haret'' (1 S 22:5) y el ''bosque de Efraín'' (2 S 18:6) sirven de escenario para eventos bíblicos fundamentales. Jos 17:15-18 lo usa de forma práctica: si la región montañosa es demasiado estrecha, sube al bosque y desmóntalo. En Sal 132:6, el término parece funcionar como nombre de lugar (Yaar) vinculado a la estancia del Arca en Quiriat-jearim, ''ciudad de los bosques''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3293b', 'spa', 'panal de miel, miel silvestre del bosque', 'Sustantivo que designa el panal lleno de miel silvestre, distinto de la palabra más común para ''bosque'' (aunque posiblemente emparentado etimológicamente). Aparece en tres pasajes memorables: el difícil texto de 1 Samuel 14:25-26, donde los ojos de Jonatán se iluminan al probar el panal a pesar del juramento de Saúl (el texto masorético es oscuro, pero las versiones confirman miel/panal); y Cantares 5:1, donde el amado dice ''he comido mi panal con mi miel''. El término designa la miel silvestre aún en su panal natural, en contraste con la miel extraída, evocando dulzura en su forma más pura y abundante, un manjar raro en el mundo antiguo donde el azúcar era desconocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3302', 'spa', 'Verbo que significa ''ser hermoso, ser bello'' (Qal); ''embellecer, adornar'' (Piel); ''embellecerse'' (Hitpael)', 'Esta raíz verbal es el fundamento del célebre adjetivo yafeh (''hermoso'') y abarca desde la descripción de la belleza inherente hasta su creación activa. En la conjugación Qal celebra la hermosura natural: las caricias de la amada en Cantares 4:10, los pies gráciles de la sulamita en 7:1 y la transformación de Jerusalén en belleza deslumbrante en Ezequiel 16:13. Las conjugaciones Piel y Hitpael pasan a la embellecimiento intencional: artesanos adornando un ídolo con plata en Jeremías 10:4, y Judá pintándose los ojos y engalanándose para atraer aliados en Jeremías 4:30.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3303', 'spa', 'Hermoso, bello, apuesto (de personas, animales, objetos); ocasionalmente ''apropiado'' o ''conveniente'' en contextos sapienciales.', 'Hermoso, bello, apuesto (de personas, animales, objetos); ocasionalmente ''apropiado'' o ''conveniente'' en contextos sapienciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3305', 'spa', 'Jope (actual Jaffa), ciudad portuaria del Mediterráneo asignada a Dan, al noroeste de Jerusalén', 'Jope fue el principal puerto mediterráneo del antiguo Israel, el lugar donde Jonás intentó huir del mandato de Dios y donde llegaba la madera de cedro del Líbano para los proyectos del templo de Salomón y Zorobabel. Situada en la costa al noroeste de Jerusalén, esta ciudad aparece en registros egipcios, asirios y fenicios bajo nombres similares (Ye-pu, Jappu), confirmando su importancia estratégica de larga data. Los griegos la conocían como Ioppa, y en tiempos del Nuevo Testamento fue donde Pedro ejerció su ministerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3308', 'spa', 'Belleza, esplendor, hermosura — la gracia exterior de personas, ciudades o la tierra', 'Belleza, esplendor, hermosura — la gracia exterior de personas, ciudades o la tierra');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3309', 'spa', 'Jafía — nombre propio de persona y lugar, posiblemente ''él resplandece''', 'Nombre que designa tanto a personas como a un lugar, derivado probablemente de la raíz יָפַע (''brillar, resplandecer''). Como nombre personal, Jafía identifica a un rey cananeo de Laquis que se unió a la coalición contra Gabaón (Jos 10:3) y también a un hijo de David nacido en Jerusalén (2 S 5:15; 1 Cr 3:7; 14:6). Como topónimo, Jafía señala una ciudad en la frontera de Zabulón (Jos 19:12), posiblemente la actual Yafa cerca de Nazaret. La LXX traduce el nombre real como Iephtha pero el del hijo davídico de forma diferente, lo cual sugiere fluidez textual temprana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3310', 'spa', 'Yaflet/Jaflet, nombre personal aserita en los registros genealógicos', 'Nombre propio que aparece exclusivamente en las genealogías de la tribu de Aser en 1 Crónicas 7:32-33. El nombre se menciona tres veces en rápida sucesión, tanto como descendiente de Heber (v. 32, donde un manuscrito lee יַפְלָט en su lugar) como ancestro de otros aseritas (v. 33, dos veces). Las versiones griegas lo transliteran de diversas maneras (Ιφαμηλ, Αφαληκ, Ιαφαλητ), mostrando la incertidumbre típica al transliterar nombres propios hebreos. La etimología y el significado permanecen oscuros, aunque la raíz podría relacionarse con liberación o escape (פלט).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3312', 'spa', 'Jefuné — nombre propio llevado por el padre de Caleb el quenizeo y por un jefe de clan aserita', 'Jefuné — nombre propio llevado por el padre de Caleb el quenizeo y por un jefe de clan aserita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3313', 'spa', 'Resplandecer, irradiar rayos de luz; usado especialmente de la gloria teofánica de Dios manifestándose en esplendor.', 'Este verbo en Hiphil capta el momento dramático en que la luz irrumpe con fuerza, particularmente el esplendor radiante de la aparición de Dios. En Deuteronomio 33:2, YHWH ''resplandeció'' desde el monte Parán en la gran bendición teofánica de Moisés. El Salmo 50:2 declara que desde Sion, perfección de hermosura, Dios ha ''resplandecido''. El verbo transmite una fuerza casi física: la luz no simplemente existe, sino que irrumpe activamente y se manifiesta. En los discursos de Job describe una luminosidad tanto anhelada como aterradora (Job 3:4; 10:22; 37:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3315', 'spa', 'Jafet (יֶפֶת) — tercer hijo de Noé; antepasado de los pueblos de Asia Menor y las tierras costeras', 'Jafet (יֶפֶת) es uno de los tres hijos de Noé, mencionado siempre junto a Sem y Cam. Su nombre podría derivar de la raíz פתה (''ser amplio, espacioso''), conexión que se aprovecha en la bendición de Noé: ''Engrandezca Dios (יַפְתְּ) a Jafet'' (Gn 9:27). Los catorce descendientes de Jafet enumerados en la Tabla de las Naciones (Gn 10:2-5) incluyen a Gomer, Magog, Madai, Javán, Tubal, Mesec y Tirás, pueblos asociados tradicionalmente con Anatolia, el Egeo, la meseta iraní y las costas del Mar Negro. Jafet y Sem cubrieron juntos la desnudez de su padre (Gn 9:23), obteniendo una bendición contrastante con la maldición de Cam. El nombre reaparece en la genealogía del Cronista (1 Cr 1:4-5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3316', 'spa', 'Yiphtach — ''el abre''; el juez galaadita Jefté (Jue 11-12) y una ciudad en la Sefela de Judá (Jos 15:43)', 'Yiphtach — ''el abre''; el juez galaadita Jefté (Jue 11-12) y una ciudad en la Sefela de Judá (Jos 15:43)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3318', 'spa', 'salir, partir, brotar; Hifil: sacar, hacer salir, producir. El verbo hebreo fundamental de movimiento hacia afuera.', 'יָצָא es el verbo primario de la Biblia hebrea para todo tipo de movimiento hacia afuera: una persona que sale de una casa, un ejército que marcha a la batalla, agua que brota de un manantial, palabras que proceden de una boca, descendencia que sale de un vientre. Con más de mil ocurrencias, ancla algunos de los momentos más definitorios de las Escrituras: el éxodo de Israel de Egipto, el sol saliendo sobre Sodoma cuando Lot escapa (Gn 19:23) y el fuego que ''salió de delante del SEÑOR'' en el Sinaí (Lv 9:24). El Hifil causativo añade un agente teológico al movimiento: Dios es quien ''sacó a Israel de Egipto,'' fórmula repetida tan frecuentemente que adquiere carácter casi credal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3320', 'spa', 'Apostarse, tomar posición; Hitpael reflexivo: presentarse ante Dios o autoridad, mantenerse firme, resistir. יָצַב aparece exclusivamente en el tallo ', 'Apostarse, tomar posición; Hitpael reflexivo: presentarse ante Dios o autoridad, mantenerse firme, resistir. יָצַב aparece exclusivamente en el tallo Hitpael en el hebreo bíblico, confiriéndole una cualidad inherentemente reflexiva y deliberada: uno no simplemente está de pie, sino que se aposta con propósito. La palabra se mueve fluidamente entre el posicionamiento físico (Miriam apostándose junto al Nilo para vigilar la cesta de su hermano, Éx 2:4), la presentación formal ante autoridad divina o humana (Israel reuniéndose ante Yahvé en el Sinaí, Éx 19:17), y la resistencia resuelta ante la oposición (Éx 14:13, ''estad firmes y ved la salvación del SEÑOR''). El cognado árabe waṣaba (''ser constante, firme'') preserva el sentido de firmeza deliberada y asentada de la raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3322', 'spa', 'Poner, colocar o apostar algo o a alguien; establecer a una persona en un cargo o posición', 'Poner, colocar o apostar algo o a alguien; establecer a una persona en un cargo o posición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3323', 'spa', 'Aceite fresco, aceite de oliva nuevo; aceite recién prensado enumerado entre los productos básicos de la tierra junto con el grano y el vino', 'Aceite fresco, aceite de oliva nuevo; aceite recién prensado enumerado entre los productos básicos de la tierra junto con el grano y el vino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3324', 'spa', 'Yitshar (Izhar) — levita, hijo de Coat y nieto de Leví, ancestro del clan izharita que incluye a Coré.', 'Yitshar (יִצְהָר, también transliterado Izhar) fue hijo de Coat, nieto de Leví y fundador del clan izharita dentro del sacerdocio levítico. Su importancia genealógica es considerable: de su línea descendió Coré, quien encabezó la célebre rebelión contra Moisés (Núm 16:1). El nombre aparece de manera constante en las genealogías levíticas de Éxodo, Números y Crónicas (Éx 6:18, 21; Núm 3:19; 1 Cr 6:2; 23:12, 18). La Septuaginta lo transcribe Ισσααρ. Aunque el sustantivo común yitshar significa ''aceite fresco'', el nombre propio aquí identifica estrictamente al ancestro levita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3325', 'spa', 'Los izharitas, familia levítica descendiente de Izhar hijo de Coat', 'Este sustantivo gentilicio designa a los descendientes de Izhar, quien fue hijo de Coat y nieto de Leví. Los izharitas formaban uno de los clanes coatitas responsables del servicio en el santuario de Israel. Los libros de Números y Crónicas registran sus asignaciones y líderes dentro de la organización levítica, mostrando cómo Israel rastreaba las líneas familiares para los deberes de culto a lo largo de las generaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3326a', 'spa', 'Lecho, diván (poético); cámara lateral, anexo arquitectónico (en el templo de Salomón)', 'El sustantivo יָצוּעַ (yatsua'') abarca dos significados claramente diferenciados, unidos por la idea de algo extendido o dispuesto a lo largo. En contextos poéticos e íntimos designa un lecho o diván: la maldición de Jacob a Rubén menciona ''mi lecho'' profanado (Gn 49:4), y el salmista medita sobre Dios ''en mi cama'' (Sal 63:7). En la descripción arquitectónica del templo de Salomón (1 R 6:5-10), la misma raíz produce ''cámaras laterales'', los anexos escalonados construidos contra los muros del templo. La conexión semántica reside en la raíz que significa extender o tender, ya sea ropa de cama o pavimento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3326b', 'spa', 'cámara lateral, aposento adosado (término arquitectónico para las dependencias del templo)', 'Término arquitectónico que designa las cámaras laterales o aposentos adosados al templo de Salomón, descritos en 1 Reyes 6:5-10. Estas dependencias se construyeron contra los muros exteriores del templo en tres de sus lados, formando una estructura de tres pisos que no recaía sobre los muros principales del santuario. El texto hebreo presenta dificultades, con variantes Qeré/Ketiv y propuestas académicas de leer הַצֵּלָע según la Septuaginta y los textos paralelos de Ezequiel 41:5-8. Estas cámaras probablemente servían para almacenar los utensilios sagrados, las vestiduras sacerdotales y otros objetos del culto, ampliando el espacio funcional del templo sin comprometer la arquitectura sagrada del recinto principal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3327', 'spa', 'Isaac (Yitsjaq) — patriarca, hijo de Abraham y Sara; su nombre significa ''él ríe''.', 'Yitsjaq (Isaac) es el segundo patriarca de Israel, el hijo largamente prometido que nació a Abraham y Sara en su vejez. Su nombre, que significa ''él ríe'', juega con la risa de incredulidad de Sara (Gn 18:12) y su posterior alegría (Gn 21:6). Isaac aparece en más de 100 versículos que abarcan el Pentateuco, los libros históricos y los Salmos. Es padre de Jacob y Esaú, y su casi-sacrificio en el monte Moria (Gn 22) constituye uno de los episodios definitorios de la Escritura. Amós emplea ''casa de Isaac'' como sinónimo de Israel (Am 7:16). Las traducciones transliteran uniformemente el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3330', 'spa', 'Cierto, seguro, verdadero; firme y confiable (arameo, en Daniel)', 'Adjetivo arameo que aparece exclusivamente en Daniel para expresar certeza, seguridad y verdad. Cuando Nabucodonosor declara ''de cierto'' (min-yaṣṣîb) que los sabios están ganando tiempo (Dn 2:8), la palabra tiene peso judicial: es el veredicto firme de un rey. En Daniel 2:45, la interpretación del sueño se proclama ''cierta''. El uso exclamativo en Daniel 3:24 (''¡sin duda!'') muestra una fuerza enfática intensificada. La forma femenina sustantivada en Daniel 7:16 significa ''la verdad'': Daniel busca el sentido fidedigno de su visión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3331', 'spa', 'extender, tender (como una cama o lecho); hacer su lecho en el Seol', 'Este verbo poco frecuente aparece en textos poéticos y proféticos describiendo la acción de extender o tender algo, como quien prepara una cama o un lecho. Isaías lo emplea con tono de burla al preguntar si extender cilicio y ceniza constituye realmente un ayuno aceptable, mientras el salmista contempla que aun si tendiera su lecho en el Seol, Dios estaría allí. Los cognados arameos y árabes sugieren significados relacionados con tender o extender, y el arameo desarrolla además un sentido de ''explicar'' o ''exponer'', quizá por la metáfora de desplegar ideas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3332', 'spa', 'Verter o derramar líquido (aceite, agua, sangre); fundir metal en un molde; raramente, ser firme/duro o depositar algo. El verbo יָצַק se centra en el', 'Verter o derramar líquido (aceite, agua, sangre); fundir metal en un molde; raramente, ser firme/duro o depositar algo. El verbo יָצַק se centra en el movimiento controlado de un líquido: verter aceite para la unción (Gn 28:18; Éx 29:7), verter agua para el lavamiento (2 R 3:11), derramar sangre al pie del altar (Lv 8:15). Pero יָצַק tiene una notable extensión industrial: cuando lo que se vierte es metal fundido, el verbo se convierte en ''fundir'': basas de bronce para el tabernáculo (Éx 26:37), las columnas de bronce del templo de Salomón (1 R 7:46), los doce toros de bronce bajo el mar de fundición. Dos ocurrencias aisladas llevan la semántica más lejos: Job 11:15 usa el participio pasivo para significar ''firme'' o ''duro'' —como si el líquido vertido en un molde se hubiera solidificado— y 2 S 15:24 lo emplea para depositar el arca, una extensión de verter a colocar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3334', 'spa', 'Estar angustiado, ser estrecho o constreñido; en Hifil, oprimir o causar angustia a otros', 'Un verbo enraizado en la imagen física de estrechez y constricción, que se extiende naturalmente al ámbito emocional de la angustia y la aflicción. Cuando Jacob supo que Esaú venía con cuatrocientos hombres, se angustió en gran manera (Gn 32:7), y cuando los hombres de David hablaban de apedrearlo en Siclag, él también se afligió profundamente (1 S 30:6). El sentido espacial aparece en pasajes como Isaías 49:19, donde una tierra restaurada será ''demasiado estrecha'' para sus habitantes. La única ocurrencia Hifil en Nehemías 9:27 describe a enemigos que oprimieron a Israel, captando la fuerza causativa de esta conjugación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3335', 'spa', 'Formar, modelar, dar forma; del alfarero moldeando arcilla, Dios creando a la humanidad y el mundo, y metafóricamente, idear un plan o propósito. יָצַ', 'Formar, modelar, dar forma; del alfarero moldeando arcilla, Dios creando a la humanidad y el mundo, y metafóricamente, idear un plan o propósito. יָצַר es el verbo del escultor y del alfarero: la palabra para dar forma a la materia prima con propósito. Su ocurrencia más famosa es Gn 2:7, donde Dios יָצַר al ser humano del polvo de la tierra, una imagen que resuena a lo largo de las Escrituras siempre que aparece la metáfora del Creador como artesano. La forma participial יוֹצֵר (''alfarero, el que forma'') se convirtió en una designación estándar tanto para alfareros humanos (1 Cr 4:23, Is 30:14) como para Dios, el supremo Formador de todas las cosas (Is 45:18). Los profetas explotan la metáfora del alfarero y la arcilla con poderoso efecto teológico: ''¿Dirá la arcilla al que la forma: qué estás haciendo?'' (Is 45:9). Una extensión pequeña pero significativa lleva la palabra al ámbito de la formación mental: idear o determinar un plan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3336', 'spa', 'Forma, constitución, inclinación; lo moldeado por un alfarero, la constitución de una criatura o la tendencia del corazón humano', 'Derivado del verbo יָצַר (''formar, moldear''), este sustantivo abarca desde la obra de un alfarero hasta los movimientos ocultos de la mente humana. En Génesis 6:5 y 8:21 designa la ''inclinación'' del corazón, esa disposición profunda hacia el bien o el mal que el pensamiento rabínico posterior cristalizó como yetser ha-tov y yetser ha-ra. En Isaías 29:16 y Habacuc 2:18 denota el producto concreto de la artesanía: una vasija, un ídolo, algo formado por manos. Salmo 103:14 ocupa el tierno punto medio — ''Él conoce nuestra condición'' — donde יֵצֶר apunta a la frágil constitución del cuerpo humano, nacido del polvo. El árabe taṣawwur (''imagen mental'') y jibilla (''constitución natural'') reflejan estos sentidos superpuestos, mostrando que la tensión entre lo formado exteriormente y lo formado interiormente no es exclusiva del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3337', 'spa', 'Yéser, hijo de Neftalí y ancestro epónimo del clan jezerita', 'Nombre personal y de clan correspondiente a uno de los hijos de Neftalí. Aparece en tres listas genealógicas paralelas: Génesis 46:24 (hijos que bajaron a Egipto), Números 26:49 (censo del desierto que registra al clan jezerita) y 1 Crónicas 7:13 (genealogía tribal). El nombre podría significar ''forma'' o ''modelado'', vinculado a la raíz יצר (formar, modelar). Se le ha clasificado erróneamente bajo el dominio de ''dificultad y aflicción'', probablemente por confusión con el sustantivo יֵצֶר (inclinación, angustia), que comparte la misma grafía consonántica pero constituye un lexema distinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3341', 'spa', 'Encender, prender fuego (Hifil); ser quemado o encendido (Nifal); arder, incendiarse (Qal).', 'Encender, prender fuego (Hifil); ser quemado o encendido (Nifal); arder, incendiarse (Qal).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3342', 'spa', 'Lagar o cuba de vino — una pila excavada en la roca para recoger el jugo de las uvas pisadas', 'Lagar o cuba de vino — una pila excavada en la roca para recoger el jugo de las uvas pisadas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3344', 'spa', 'Arder o encenderse; como sustantivo, hogar o lugar donde se mantiene vivo el fuego.', 'Verbo de arder y encenderse con fuerte respaldo cognado en toda la familia semítica: arameo yeqad, siríaco yiqed y árabe waqada significan ''arder''. En las Escrituras porta una intensa carga teológica: la ira de Dios arde hasta el Seol (Deut 32:22), el juicio divino se enciende como fuego (Isa 10:16), y una llama perpetua debe mantenerse ardiendo sobre el altar (Lev 6:9, 12-13). El único uso nominal en Isaías 30:14 nos da yaqud, el hogar o fogón del cual se recogen las brasas, una imagen doméstica concreta en medio de un pasaje de juicio demoledor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3345', 'spa', 'Arder (arameo); usado exclusivamente en Daniel 3 para describir el horno ardiente donde fueron arrojados los tres fieles.', 'Este verbo arameo aparece únicamente como participio femenino singular en Daniel 3, siempre modificando al horno de fuego (attun nura yaqidta) en el que fueron arrojados Sadrac, Mesac y Abednego. Las ocho ocurrencias se concentran en esta única narrativa dramática, describiendo el horno en estado de combustión activa. La forma participial enfatiza el carácter continuo e intenso del fuego. El español lo traduce como ''ardiente'', el francés como ''ardente'', y el alemán condensa toda la imagen en una sola palabra compuesta, ''Feuerofen'' (horno de fuego).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3351', 'spa', 'ser viviente, todo lo existente; sustancia, existencia (usado colectivamente)', 'Sustantivo que denota la sustancia, la existencia o el conjunto de los seres vivientes. La expresión כָּל־הַיְקוּם (''todo lo existente'') aparece en Génesis 7:4, 23 refiriéndose a todas las criaturas —humanas y animales— que Dios borraría en el diluvio. En Deuteronomio 11:6 se emplea en un sentido más restringido para designar la casa y las posesiones de Datán y Abiram, tragados por la tierra. El término capta la totalidad de cuanto vive y subsiste: todo aquello que tiene ser y se mantiene en pie sobre la tierra, lo cual hace que su destrucción en el juicio divino resulte aún más devastadora y absoluta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3353', 'spa', 'pajarero, cazador de aves; el que tiende lazos y trampas para atrapar pájaros', 'Sustantivo que designa al pajarero o cazador de aves, aquel que tiende trampas y lazos para capturarlas. La palabra aparece tres veces, siempre con connotaciones ominosas. El Salmo 91:3 promete liberación del ''lazo del cazador'' en un contexto de protección divina. Proverbios 6:5 exhorta a escapar ''de la mano del cazador'' como un pájaro que huye. Jeremías 5:26 describe a los malvados que acechan como pajareros tendiendo trampas, solo que sus presas son personas, no aves. El pajarero se convierte así en una poderosa metáfora bíblica del peligro, el engaño y quienes explotan a los indefensos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3355', 'spa', 'Joctán — hijo de Heber y ancestro de tribus árabes en la Tabla de las Naciones (Génesis 10; 1 Crónicas 1).', 'Nombre propio hebreo (יָקְטָן) que designa a un hijo de Heber y hermano de Peleg en la genealogía semita. Joctán es presentado como el ''padre'' —es decir, el ancestro epónimo— de trece grupos tribales árabes concentrados en Yemen y el sur de Arabia (Gn 10:25–29; 1 Cr 1:19–23). Mientras la línea de su hermano Peleg conduce a Abraham e Israel, la de Joctán traza los pueblos semíticos de la península arábiga. La tradición árabe lo identifica con Qaḥṭān, el legendario progenitor de los árabes del sur. La etimología del nombre es discutida, aunque BDB lo relaciona con una raíz árabe que significa ''golpear''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3359', 'spa', 'Yeqamyá/Jocmeam, nombre personal en la genealogía de Judá', 'Nombre personal que significa algo como ''Yahvé establecerá'' o ''que Yah levante'', construido sobre la raíz קום (levantarse, establecer). Aparece tres veces en las genealogías de 1 Crónicas, todas dentro de la tribu de Judá: dos veces en 2:41 (lo que sugiere una repetición textual o dos individuos con el mismo nombre en proximidad genealógica) y una vez en 3:18 entre los descendientes de Jeconías, el rey de Judá llevado al exilio. El elemento teofórico del nombre expresa la esperanza en la acción restauradora de Yahvé, algo especialmente conmovedor en el contexto de la genealogía real tras el destierro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3362', 'spa', 'Jocneam, ciudad cananea en Zabulón que luego fue designada ciudad levítica', 'Nombre de una ciudad cananea mencionada en los relatos de la conquista y repartición de la tierra bajo Josué. Aparece primero en la lista de reyes derrotados (Josué 12:22), donde se la identifica con la expresión «del Carmelo», indicando su cercanía al monte Carmelo. Fue asignada al territorio de Zabulón (Josué 19:11) y posteriormente designada como ciudad levítica (21:34), mostrando su transición de fortaleza cananea a posesión israelita y herencia sacerdotal. El sitio se identifica generalmente con Tell Qeimun, un tell estratégico en el valle de Jezreel que controlaba las rutas entre la llanura costera y el valle interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3363', 'spa', 'Ser dislocado o alienado (Qal); colgar o empalar públicamente (Hifil); los colgados (participio Hofal).', 'Un verbo cuyo campo semántico abarca desde la dislocación hasta la ejecución. En el Qal, describe algo arrancado de su lugar: la cadera de Jacob en Peniel (Gn 32:25) y, metafóricamente, un alma apartada o enajenada de alguien (Jer 6:8; Ez 23:17-18). El Hifil pasa a un sentido causativo sombrío: colgar o empalar públicamente como castigo judicial, como se ve en Números 25:4 y la ejecución de los descendientes de Saúl por parte de los gabaonitas (2 S 21:6, 9). El cognado árabe waqa''a (''caer, caer sobre'') conserva la fuerza física de la raíz. Las versiones antiguas discrepan sobre el método exacto: los traductores griegos sugieren ''exposición al sol'', el Targum dice ''crucificar'' y otros ''arrojar desde una altura'', lo cual refleja una auténtica incertidumbre sobre la forma precisa de ejecución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3364', 'spa', 'Despertar, despertarse — salir del sueño, usado tanto del despertar natural como del despertar metafórico de un estado de estupor', 'El verbo יָקַץ (yaqats) significa despertar o despertarse del sueño, típicamente en el tronco Qal. Describe el momento de transición del sueño a la conciencia vigil, a menudo en puntos narrativamente decisivos: Noé despertó de su vino y supo lo que Cam había hecho (Gn 9:24), Jacob despertó en Betel declarando «Ciertamente YHWH está en este lugar» (Gn 28:16), y Faraón despertó de sus sueños proféticos (Gn 41:4, 7, 21). El famoso sueño-juicio de Salomón concluye con su despertar (1 R 3:15). El verbo también posee matices figurados en la literatura sapiencial, como cuando el justo despierta y descubre que la prosperidad de los impíos se ha desvanecido (Sal 73:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3365', 'spa', 'Ser precioso, estimado o preciado; hacer raro o escaso (Hifil); ser tasado a un precio', 'En su esencia, este verbo transmite el peso del valor, ya sea una preciosidad intrínseca o un valor asignado. Cuando el nombre de David «se hizo precioso» (1 S 18:30), o cuando un capitán suplica «sea mi vida preciada ante tus ojos» (2 R 1:13-14), el tronco Qal expresa genuina estima y honor. El Hifil causativo interioriza esto: Dios hará al ser humano «más raro que el oro fino» (Is 13:12), y Proverbios aconseja hacer «raro» tu pie en la casa del vecino (Pr 25:17). La amarga ironía de Zacarías —«el magnífico precio en que fui valorado» (Zac 11:13)— lleva la raíz al terreno de la tasación comercial, sentido que también posee el cognado arameo yəqar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3366', 'spa', 'Preciosidad, tesoro; honor, estima, gloria; precio o valor monetario', 'Preciosidad, tesoro; honor, estima, gloria; precio o valor monetario');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3367', 'spa', 'Honor, gloria, esplendor; sustantivo arameo que denota dignidad real, magnificencia y peso de estima', 'Este sustantivo arameo aparece exclusivamente en Daniel, donde describe el honor y la gloria otorgados o retirados a los gobernantes. Nabucodonosor recibe ''gloria y honor'' junto con su reino (Dn 2:37; 5:18), y esa misma gloria le es arrebatada durante su período de locura antes de serle restituida (Dn 4:33, 36). La palabra es paralela al hebreo kavod en su campo semántico, combinando nociones de esplendor, peso de reputación y magnificencia regia. Siempre aparece emparejada con otros términos de soberanía, reforzando que el verdadero honor proviene del Dios que da y quita los reinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3368', 'spa', 'Precioso, costoso, raro; de gran valor ya sea material, personal o por su escasez.', 'Precioso, costoso, raro; de gran valor ya sea material, personal o por su escasez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3369', 'spa', 'Poner una trampa, tender un lazo (Qal activo); ser atrapado, caer en la trampa (Nifal/Pual pasivo).', 'El verbo יָקֹשׁ (yaqosh) toma su imagen del mundo de la caza con trampas y lazos para describir tanto el acto deliberado de tender una trampa como el estado resultante de quedar atrapado en ella. En el Qal, el cazador es el sujeto: Dios mismo declara ''te puse trampa, oh Babilonia'' (Jer 50:24), y los impíos tienden lazos para el justo (Sal 141:9). En el Nifal y el Pual, la víctima es el sujeto: atrapada por la idolatría (Dt 7:25), por palabras imprudentes (Pr 6:2) o por el juicio divino (Is 8:15). Las traducciones árabes distinguen claramente entre نَصَبَ فَخًّا (''poner una trampa'') para el activo y يُصْطَادُوا (''ser atrapados'') para el pasivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3370', 'spa', 'Jocsán, hijo de Abraham por Cetura, padre de Seba y Dedán', 'Jocsán aparece en la Tabla de las Naciones como uno de los hijos de Abraham con su concubina Cetura, tomada después de la muerte de Sara. A través de sus hijos Seba y Dedán, Jocsán se convirtió en ancestro de grupos tribales árabes que mantuvieron relaciones comerciales con Israel. Las genealogías paralelas en Génesis y Crónicas preservan su nombre como parte del legado familiar más amplio de Abraham que se extiende hacia la península arábiga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3372', 'spa', 'Temer, tener miedo; reverenciar o sentir temor de Dios; (Nifal ptc.) temible, terrible; (Piel) amedrentar, aterrorizar.', 'Verbo primario del vocabulario emocional hebreo, que abarca todo el espectro desde el terror visceral hasta la más profunda reverencia. En su Qal describe el pavor ante el peligro (Gn 15:1, ''No temas'') y el santo temor debido a Dios (Dt 6:13). Su participio Nifal se convirtió prácticamente en un epíteto divino: ''el Dios temible'' (Dt 7:21), mientras que su Piel intensifica la acción en intimidación deliberada, como cuando los agentes de Sanbalat intentaron amedrentar a Nehemías (Neh 6:9). El árabe escinde lo que el hebreo unifica: khafa para el terror, ittaqa o khashiya para la piedad, y mahib para lo imponente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3373', 'spa', 'Temeroso, reverente; como adjetivo o participio: el que teme a Dios (reverencia piadosa) o el que tiene miedo (temor emocional). יָרֵא como adjetivo o', 'Temeroso, reverente; como adjetivo o participio: el que teme a Dios (reverencia piadosa) o el que tiene miedo (temor emocional). יָרֵא como adjetivo o participio verbal se sitúa en la intersección de dos experiencias humanas profundamente distintas: la reverencia llena de asombro del piadoso ante Dios, y el temblor aterrorizado del que tiene miedo. La construcción plural ''los que temen a YHWH'' (יִרְאֵי יהוה) se convierte casi en una designación técnica para la comunidad fiel en los Salmos y la literatura sapiencial: un marcador de identidad espiritual más que una descripción emocional. La genialidad de la palabra reside en que ambos sentidos comparten una intuición de raíz: la respuesta adecuada ante el Dios viviente no es la comodidad casual sino la atención reverente y temblorosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3374', 'spa', 'Temor, reverencia, asombro; abarcando desde el terror ante el peligro hasta la piedad devota hacia Dios.', 'Temor, reverencia, asombro; abarcando desde el terror ante el peligro hasta la piedad devota hacia Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3378', 'spa', 'Jerobaal (''que Baal contienda''); nombre alterno dado a Gedeón tras destruir el altar de Baal', 'Designación alternativa de Gedeón hijo de Joás, otorgada después de derribar el altar de Baal en Ofra. Jueces 6:32 ofrece la etimología popular: su padre declaró ''que Baal contienda contra él,'' desafiando al dios pagano a defender su propio honor. El nombre persiste a lo largo del ciclo de Gedeón (Jue 7-9), dominando la narrativa de Abimelec, donde las nueve apariciones del capítulo 9 usan Jerobaal en lugar de Gedeón. Samuel lo invoca en su discurso de despedida (1 S 12:11). En 2 Samuel 11:21, la variante Jeroboset reemplaza ba''al con boshet (''vergüenza''), reflejando la incomodidad escribal posterior con nombres que contenían el elemento Baal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3379', 'spa', 'Jeroboam — nombre propio que significa ''el pueblo se multiplica''; dos reyes del reino del norte de Israel.', 'Yarovam (Jeroboam) es un nombre propio hebreo que probablemente significa ''el pueblo se multiplica'' (de yarov + am). Identifica a dos reyes del reino del norte: Jeroboam I hijo de Nabat, quien lideró la secesión de las diez tribus y estableció centros de culto rivales en Dan y Betel (1 R 12-14), y Jeroboam II hijo de Joás, quien presidió un periodo de expansión territorial (2 R 14:23-29). El primero domina el registro bíblico, citado formulariamente como el pecador arquetípico que ''hizo pecar a Israel'' (1 R 15:30; 16:26). Las traducciones de todas las lenguas transliteran el nombre de modo reconocible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3381', 'spa', 'Bajar, descender, hacer descender; descenso físico de un lugar más alto a uno más bajo, incluyendo personas, líquidos y objetos.', 'El verbo yarad (381 apariciones) expresa movimiento descendente en múltiples conjugaciones. En Qal describe el descenso físico: personas que bajan de montañas o viajan a ciudades más bajas (242 apariciones), líquidos que fluyen hacia abajo (lágrimas, aceite, agua) y el participio sustantivado ''los que descienden a la fosa'' en contextos poéticos (44 apariciones). El Hifil causativo traslada el sujeto a un agente que hace bajar o desciende personas u objetos (53 apariciones), mientras que el Hofal marca el descenso pasivo (6 apariciones). La trayectoria semántica central es constante: movimiento de mayor a menor elevación, ya sea geografía literal, flujo vertical de líquidos o descenso metafórico al Seol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3382', 'spa', 'Yered (Jered), nombre propio que significa ''descenso'', llevado por el patriarca antediluviano y un hombre de Judá', 'Yered es conocido principalmente como el patriarca de la sexta generación desde Adán por la línea de Set, padre de Enoc (Gn 5:15-20). Su nombre probablemente deriva de la raíz yarad (''descender''), que la tradición posterior a veces relacionó con el descenso de los Vigilantes. Según la genealogía de Génesis, vivió 962 años. Un segundo Yered aparece brevemente en la genealogía de Judá como figura asociada a Gedor (1 Cr 4:18). La Septuaginta traduce consistentemente el nombre como Iared, reflejado en las formas castellanas Jared y Jered.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3383', 'spa', 'Jordán — el río principal de Palestina, que fluye desde el mar de Galilea hacia el sur hasta el mar Muerto.', 'El Jordán (Yarden) es el curso de agua definitorio de la geografía bíblica, que funciona tanto como frontera física como símbolo teológico. Su nombre probablemente deriva de yarad (''descender''), describiendo su pronunciado descenso desde Galilea hasta el mar Muerto, el punto más bajo de la tierra. El cruce del Jordán se convierte en un motivo poderoso: Abram contempla su llanura (Gn 13:10-11), Israel entra en la tierra prometida a través de sus aguas divididas (Jos 3) y Elías y Eliseo lo cruzan milagrosamente (2 R 2). En el Nuevo Testamento es el lugar del bautismo de Jesús. Todas las lenguas preservan el nombre propio con mínima adaptación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3384a', 'spa', 'Disparar (flechas); en pasivo (Hofal), ser regado o saturado — variante ortográfica aramea de yarah', 'Variante con ortografía aramea del verbo común yarah, esta forma posee dos significados distintos según la conjugación. En el Hifil activo describe el acto de disparar flechas, como cuando los soldados de Joab dispararon contra Urías desde la muralla de Rabá (2 S 11:24) y en la forma participial ''los flecheros'' que hirieron a Saúl (1 S 31:3). La única aparición en Hofal, en Proverbios 11:25, cambia completamente el sentido: ''el que riega será también regado'', un hermoso proverbio recíproco donde la generosidad retorna al dador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3384b', 'spa', 'Lanzar, disparar, enseñar o dirigir; uniendo el acto físico de arrojar proyectiles con la transmisión autoritativa de instrucción. Esta raíz mantiene ', 'Lanzar, disparar, enseñar o dirigir; uniendo el acto físico de arrojar proyectiles con la transmisión autoritativa de instrucción. Esta raíz mantiene unidos dos campos semánticos que parecen distantes pero comparten una imagen común: impulsar algo hacia un objetivo. En su tallo Qal, יָרָה significa lanzar o disparar: arrojar los carros de Faraón al mar (Éx 15:4) o disparar flechas (1 S 20:20). En el Hifil, la misma raíz se convierte en ''enseñar'', como si se lanzara el conocimiento hacia el aprendiz. El árabe preserva ambas trayectorias: رَمَى (lanzar) y عَلَّمَ (enseñar). El sustantivo torá (''instrucción, ley'') deriva de esta misma raíz, haciendo de יָרָה uno de los verbos más trascendentales de la teología bíblica. Dos ocurrencias raras incluso se extienden a enviar lluvia (Os 6:3, 10:12), como si Dios arrojara la humedad hacia la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3389', 'spa', 'Jerusalén — la ciudad santa, capital del Israel unido y del reino del sur, centro del culto en el templo', 'יְרוּשָׁלַ͏ִם aparece 643 veces en la Biblia hebrea, lo que la convierte en uno de los topónimos más frecuentes de toda la Escritura. Su etimología sigue siendo debatida —posiblemente ''fundación de Shalem'' (deidad de la paz) o ''posesión de paz''—, pero su significado teológico es inequívoco: la ciudad donde Dios eligió poner su Nombre (Dt 12:5), donde Salomón edificó el Templo y donde los profetas anunciaron tanto juicio como restauración. Su forma permanece notablemente estable en todos los idiomas, reflejo de su condición de referente geográfico y espiritual universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3390', 'spa', 'Yerushalem (Jerusalén) — la forma aramea del nombre de la ciudad santa, usada en los textos posexílicos de Esdras y Daniel', 'Yerushalem (Jerusalén) — la forma aramea del nombre de la ciudad santa, usada en los textos posexílicos de Esdras y Daniel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3391', 'spa', 'Mes (unidad temporal lunar) o luna (el cuerpo celeste); ambos sentidos derivan del ciclo lunar', 'Sustantivo masculino cuyos dos sentidos comparten la misma raíz etimológica en el ciclo lunar. En la mayoría de sus trece apariciones funciona como término calendárico que significa ''mes,'' nombrando meses específicos en las narrativas de la construcción salomónica (el mes de Ziv, 1 R 6:37; el mes de Bul, 1 R 6:38; el mes de Etanim, 1 R 8:2) y midiendo duraciones de tiempo (Éx 2:2; Dt 21:13). En dos pasajes poéticos, sin embargo, se refiere a la luna misma como cuerpo celeste: las bendiciones de las ''lunas'' en la bendición de Moisés (Dt 33:14) y la promesa de que ''tu luna no se ocultará'' (Is 60:20). El cognado arameo yarchaa y el acadio arhu comparten este mismo doble rango semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3394', 'spa', 'Luna — el astro menor; asociada con la adoración, el cómputo del calendario y la imaginería poética de permanencia', 'Luna — el astro menor; asociada con la adoración, el cómputo del calendario y la imaginería poética de permanencia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3395', 'spa', 'Jeroham — nombre propio hebreo que significa ''que le sea mostrada compasión'', portado por varios personajes del AT', 'Nombre teofórico construido sobre la raíz r-ḥ-m (''compasión''), que expresa la plegaria ''que le sea mostrada misericordia''. Su portador más prominente es el abuelo del profeta Samuel por la línea efratía (1 S 1:1). El nombre reaparece a lo largo de diversas tribus —benjaminitas, sacerdotes levitas, un jefe danita y un capitán militar bajo Joiada— reflejando su amplia popularidad en la onomástica israelita. La Septuaginta lo transcribe de varias formas como Ieroam, Ieroboam e incluso Ierameel, evidenciando la dificultad de los traductores griegos con este nombre-plegaria distintivamente semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3396', 'spa', 'Yerajmeel — ''que Dios tenga compasión''; nombre prominente de un clan judahíta, también de un levita y un oficial real.', 'Yerajmeel (Yerachme''el) es un nombre teofórico que significa ''que El tenga compasión'', formado por la raíz de la misericordia (racham) y el nombre divino El. El portador más destacado encabeza un importante clan de Judá ampliamente documentado en 1 Crónicas 2:9-42, cuyos descendientes, los yerajmeelitas, se asentaron en el Néguev (cf. 1 S 27:10; 30:29). Un segundo Yerajmeel es levita en 1 Crónicas 24:29, y un tercero es un oficial real enviado por el rey Joacim para arrestar a Jeremías y a Baruc (Jer 36:26). El significado del nombre — una oración por la misericordia divina — resuena en todos sus portadores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3401', 'spa', 'Adversario, contendiente en una disputa; quien litiga o se opone contra alguien', 'Sustantivo derivado del verbo רִיב (contender, litigar, llevar un pleito), que designa al adversario u oponente en un conflicto. Sus tres apariciones abarcan contextos diversos: el Salmo 35:1 invoca a Yahvé para que «contienda con mis adversarios»; Isaías 49:25 promete a Sion que Dios luchará contra «el que contiende contigo»; y Jeremías 18:19 pide a Dios que atienda a «mis contendientes». El término lleva un matiz forense: no se trata simplemente de enemigos, sino de oponentes en una causa legal o verbal, de modo que la intervención divina se presenta como un acto de justicia, no de mero poder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3402', 'spa', 'Jarib, nombre propio (simeonita y líderes postexílicos)', 'Nombre propio que significa «él contiende» o «él aboga por nosotros», derivado de la raíz רִיב (litigar, llevar una causa). Aparece referido a varias personas: un hijo de Simeón en 1 Crónicas 4:24 (paralelo a יָכִין en Génesis 46:10), y figuras del período postexílico: uno enviado por Esdras para reclutar levitas (Esdras 8:16) y posiblemente el mismo individuo entre los sacerdotes que se casaron con mujeres extranjeras (10:18). El paralelo sabeo ירב confirma que este era un patrón onomástico conocido en culturas semíticas afines. El nombre expresa la confianza en que Yahvé litiga a favor de su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3404', 'spa', 'Jerías/Yeriyahu, jefe de un turno sacerdotal levítico', 'Nombre propio levítico que aparece en las descripciones de 1 Crónicas sobre la organización del servicio del templo bajo David. El nombre presenta dos grafías: יְרִיָּהוּ (Yeriyahu) en 23:19 y 24:23, y la forma abreviada יְרִיָּה (Yeriyyah) en 26:31. Las tres referencias lo identifican como jefe de uno de los turnos o divisiones levíticas. El nombre posiblemente se relaciona con יְרִיאֵל y podría significar «Yah enseña» o «fundado por Yah». Las versiones griegas muestran la variación típica al trasladar este nombre hebreo a la fonología griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3405', 'spa', 'Jericó — la antigua ciudad cananea en el valle del Jordán, primera gran conquista bajo Josué', 'Jericó — la antigua ciudad cananea en el valle del Jordán, primera gran conquista bajo Josué');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3406', 'spa', 'Jerimot / Yerimot — nombre propio que significa ''alturas'' o ''él es exaltado,'' portado por benjaminitas, levitas y otros', 'Escrito en tres variantes ortográficas (יְרֵימוֹת, יְרֵמוֹת, יְרִימוֹת), este nombre lleva el sentido de ''alturas'' o ''exaltación,'' apropiado para familias que veían elevación divina en sus hijos. Aparece entre guerreros benjaminitas (1 Cr 7:7-8; 8:14), músicos y porteros levíticos (1 Cr 23:23; 25:4, 22), un jefe neftalita (1 Cr 27:19) y un hijo de David cuya hija se casó con Roboam (2 Cr 11:18). Tres hombres con este nombre aparecen en Esdras 10 entre quienes habían tomado esposas extranjeras, dando al nombre un eco agridulce final en el canon.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3407', 'spa', 'Cortina o panel de tela, especialmente del tabernáculo o de una tienda; por extensión, la morada misma.', 'Cortina o panel de tela, especialmente del tabernáculo o de una tienda; por extensión, la morada misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3409', 'spa', 'Muslo, pierna superior (parte del cuerpo, gesto de juramento, poder procreador); lado o flanco de una estructura; base o fuste del candelabro.', 'Muslo, pierna superior (parte del cuerpo, gesto de juramento, poder procreador); lado o flanco de una estructura; base o fuste del candelabro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3411', 'spa', 'Partes extremas o remotas de una tierra; parte trasera de una estructura; recovecos más profundos; flanco o costado', 'Partes extremas o remotas de una tierra; parte trasera de una estructura; recovecos más profundos; flanco o costado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3412', 'spa', 'Jarmut (Yarmut), ciudad real cananea en la Sefela de Judá y ciudad levítica en Isacar', 'Jarmut fue una ciudad-estado cananea cuyo rey Piram se unió a la coalición de cinco reyes amorreos contra Gabaón, solo para ser derrotado por Josué en la dramática batalla con granizo y el sol detenido (Jos 10:3, 5, 23). Figura en Josué 12:11 entre las ciudades reales conquistadas, fue asignada posteriormente a la tribu de Judá en el distrito de la Sefela junto a Adulam (Jos 15:35) y repoblada tras el exilio (Neh 11:29). Una Jarmut distinta en Isacar sirvió como ciudad levítica (Jos 21:29). El sitio se identifica generalmente con Khirbet el-Yarmuk, al suroeste de Bet-Semes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3414', 'spa', 'Jeremías — nombre propio (Yirmeyahu), principalmente el profeta de Anatot; también varias otras figuras bíblicas', 'Yirmeyahu (o la forma abreviada Yirmeyah) es un nombre teofórico que probablemente significa «Yah exalta» o «Yah libera». Su portador más destacado es el profeta Jeremías hijo de Hilcías, sacerdote de Anatot, quien ejerció su ministerio durante las últimas décadas de Judá antes del exilio (Jer 1:1-3). Su nombre domina el libro que lleva su título, apareciendo en más de 130 de las 147 ocurrencias totales. Otros portadores incluyen un hombre de Libná cuya hija se casó con el rey Josías (2 Re 23:31), un guerrero gadita en tiempos de David (1 Cr 12:13) y varias figuras postexílicas (Neh 10:3; 12:1). La Septuaginta lo traduce como Ieremías, de donde proviene la forma castellana familiar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3415', 'spa', 'temblar, estremecerse; estar afligido o angustiado (del alma)', 'Este verbo poco frecuente describe el temblor o estremecimiento del alma en angustia o terror. Isaías lo emplea para retratar a los soldados moabitas cuya alma ''tiembla'' de miedo ante las fuerzas invasoras. La raíz también aparece en contextos de agitación interior y aflicción emocional, donde las cosas ''van mal'' para el espíritu de alguien. Los cognados árabes y del Targum sugieren asociaciones con debilidad, timidez o desánimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3417', 'spa', 'Escupir (en la cara de alguien) como señal de desprecio o humillación ritual', 'Verbo que significa escupir, específicamente en el rostro de alguien como acto de desprecio o afrenta pública. Ambas apariciones involucran humillación ritual o legal: Números 12:14 describe el principio de que si un padre escupiera en el rostro de su hija, ella cargaría con la vergüenza durante siete días; Moisés aplica esto al castigo de Miriam por desafiar su autoridad. Deuteronomio 25:9 prescribe que la viuda cuyo cuñado rechaza el matrimonio por levirato debe escupirle en la cara públicamente como parte del ritual de afrenta. El acto comunicaba un profundo desprecio y deshonra social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3418', 'spa', 'Vegetación verde, hierba o verdor — usado para las plantas dadas como alimento y para la hierba como símbolo de lo efímero.', 'Sustantivo masculino (יֶרֶק) que denota la cualidad del verdor o, de forma más concreta, las plantas verdes y la hierba como categoría colectiva. Aparece en momentos clave de la narrativa bíblica. En Génesis 1:30 y 9:3, pertenece a la teología de la creación: toda planta verde (יֶרֶק עֵשֶׂב) se da primero a los animales y luego, tras el diluvio, a la humanidad como alimento. En el relato de las plagas (Éx 10:15), las langostas devoran todo lo verde. Números 22:4 compara el temor de Moab hacia Israel con un buey que lame el verdor del campo. La tradición sapiencial lo emplea para expresar transitoriedad: los malvados florecen como hierba verde pero se marchitan pronto (Sal 37:2). Isaías 15:6 lo utiliza en un oráculo contra Moab donde el verdor ha perecido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3419', 'spa', 'Hierbas, hortalizas, verduras; plantas verdes cultivadas de huerto', 'Sustantivo colectivo que designa plantas verdes comestibles, hierbas y hortalizas de huerto. El término evoca producción cultivada y no vegetación silvestre. En Deuteronomio 11:10, la tierra de Egipto se compara con un ''huerto de hortalizas'' (gan-yārāq) regado con riego a pie. La viña de Nabot fue codiciada por Acab para convertirla en ''huerto de hortalizas'' (1 R 21:2). Proverbios 15:17 contrasta célebremente ''un plato de verduras donde hay amor'' con ''buey engordado y odio''. En Isaías 37:27 (= 2 R 19:26), la forma constructa describe frágiles ''brotes verdes de hierba'', subrayando la vulnerabilidad ante la destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3420', 'spa', 'Añublo o tizón (enfermedad de cultivos emparejada con asolamiento como juicio divino); palidez o ictericia (del rostro humano).', 'El sustantivo hebreo יֵרָקוֹן deriva de la raíz que significa ''verde/amarillo'' y designa dos fenómenos distintos pero relacionados, unidos por la idea de decoloración enfermiza. En cinco de sus seis apariciones se refiere a una devastadora enfermedad de los cultivos —añublo o tizón—, invariablemente emparejada con שִׁדָּפוֹן (''asolamiento, abrasamiento'') como instrumentos gemelos del juicio agrícola divino (Dt 28:22; 1 R 8:37; Am 4:9). La única aparición restante, en Jeremías 30:6, se desplaza a la fisiología humana: los rostros se tornan a יֵרָקוֹן —una palidez enfermiza o ictericia— describiendo a hombres atenazados por el terror como si estuvieran de parto. La misma raíz cromática produce dos imágenes distintas: campos arruinados y rostros cenicientos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3422', 'spa', 'verdoso, verde amarillento, verde pálido (describe manchas de enfermedad o moho)', 'Adjetivo que describe un color verdoso o verde amarillento, empleado exclusivamente en Levítico para el diagnóstico de enfermedades cutáneas y moho en casas. En Levítico 13:49 señala manchas verdosas en prendas (indicios de contaminación por moho), y en 14:37 (forma femenina plural) describe depresiones verdosas en muros. El Salmo 68:13 lo usa metafóricamente para el «brillo verdoso del oro», la iridiscencia dorada-verdosa de un metal precioso o posiblemente del electro. El cognado acadio raḳraḳḳu confirma esta designación cromática. Es vocabulario diagnóstico: colores que señalan impureza y requieren evaluación sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3423', 'spa', 'Poseer, heredar, desposeer; tomar posesión de la tierra (Qal), expulsar habitantes (Hifil), recibir herencia (Qal), empobrecerse (Nifal)', 'El verbo יָרַשׁ (232 ocurrencias) opera en un campo semántico de transferencia de propiedad y posesión territorial. El Qal (130x) significa principalmente tomar posesión de la tierra entrando y asentándose en ella, especialmente en el lenguaje deuteronómico de conquista, aunque también cubre heredar bienes como heredero legítimo (18x). El Hifil causativo (61x) desplaza el foco hacia la desposesión: expulsar o desalojar a los habitantes por la fuerza. El participio Qal (9x) funciona como sustantivo: «heredero» o «poseedor». Un uso Nifal sorprendente (4x) significa empobrecerse, reflejo inverso de la transferencia de propiedad. El español alterna entre poseer, heredar, desposeer y empobrecer según el matiz exacto de cada forma verbal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3425', 'spa', 'Posesión, herencia; propiedad territorial poseída como derecho hereditario, especialmente territorio otorgado por Dios', 'Concentrado casi enteramente en Deuteronomio y las narrativas de la conquista, yerushah nombra la tierra que pertenece a un pueblo por concesión divina o derecho ancestral. Moisés dice a Israel que no provoque a los descendientes de Esaú, porque ''yo he dado el monte Seír a Esaú como posesión'' (Dt 2:5), y la misma fórmula aparece para Moab (2:9) y Amón (2:19). Josué 1:15 extiende el término a la asignación de las tribus transjordanas. En Jeremías 32:8 resurge en la compra del campo de Jeremías — una señal de esperanza de que los derechos de propiedad serán restaurados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3426', 'spa', 'Hay, existe; partícula existencial que afirma presencia o existencia; ocasionalmente cópula con sufijos o sustantivo «riqueza»', 'יֵשׁ es la partícula existencial compacta del hebreo: una sola sílaba que cumple la función de frases verbales enteras en otros idiomas. Donde el español necesita «hay» y el francés il y a, el hebreo simplemente dice יֵשׁ. Aparece en declaraciones («hay trigo en Egipto», Gn 42:1), en preguntas exploratorias (הֲיֵשׁ, «¿hay?»), en prótasis condicionales («si hubiere cincuenta justos», Gn 18:24) y con sufijos pronominales como especie de cópula («tú eres», yeshka). La versatilidad de la palabra a través de marcos sintácticos diversos enmascara lo que es semánticamente una sola aserción: algo existe o está presente. Una ocurrencia aislada en Pr 8:21 conserva un sentido nominal arcaico, «riqueza», donde la Sabiduría promete dar a sus amantes bienes reales y tangibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3427', 'spa', 'Sentarse, habitar, morar, permanecer; (Hifil) asentar, hacer habitar; (Nifal) ser habitado; (Hofal) ser asentado', 'יָשַׁב es el verbo principal de la Biblia hebrea para expresar la permanencia en un lugar, ya sea sentarse en un trono, habitar en una ciudad o simplemente quedarse en algún sitio. Su campo semántico abarca desde el acto momentáneo de sentarse (Gn 27:19) hasta la ocupación permanente de una tierra entera; el participio יֹשֵׁב (''habitante de'') aparece centenares de veces como término casi técnico. El Hifil añade fuerza causativa —Dios sienta al solitario en familias (Sal 113:8)—, mientras que el Nifal y el Hofal expresan la voz pasiva: una tierra que es o será habitada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3434', 'spa', 'Jasobeam, uno de los valientes de David y comandante militar', 'Nombre propio de uno de los guerreros más célebres de David, que aparece en tres pasajes de Crónicas: 1 Crónicas 11:11 (entre los Tres valientes), 12:7 (un benjaminita que se unió a David en Siclag, posiblemente otro individuo) y 27:2 (comandante de la primera división mensual). El nombre corresponde a la expresión problemática יֹשֵׁב בַּשֶּׁבֶת en 2 Samuel 23:8, que los estudiosos suelen enmendar como Isbaal/Isboset. Las variantes griegas (Ιεσεβαδα, Ιεσσεβααλ, Ισβααμ) reflejan la incertidumbre textual. Pese a la confusión, Crónicas presenta consistentemente a Jasobeam como guerrero y comandante de primer orden.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3437', 'spa', 'Jasub, nombre de (1) un hijo de Isacar y (2) un israelita con esposa extranjera', 'Jasub aparece tanto como nombre de clan en la genealogía de Isacar como nombre individual en la lista de Esdras de quienes se casaron con mujeres extranjeras. El nombre significa ''él vuelve'', e Isaías emplea una forma similar (Sear-jasub, ''un remanente volverá'') como nombre simbólico de su hijo. Las variaciones de Ketiv-Qeré en el texto revelan incertidumbre escribal sobre la grafía precisa, y Crónicas preserva formas alternativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3440', 'spa', 'Isví, nombre de (1) un hijo de Aser y (2) un hijo de Saúl', 'Isví aparece como nombre de dos personajes bíblicos: uno de los hijos de Aser que fundó un clan, y uno de los hijos de Saúl. Los estudiosos del texto sugieren que el segundo Isví podría ser una forma alternativa de Is-boset, el hijo de Saúl que reinó brevemente tras la muerte de su padre. El nombre aparece en genealogías tribales y listas de la familia real, preservado con variaciones ortográficas menores en los pasajes bíblicos paralelos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3442', 'spa', 'Jesúa/Yeshúa — forma posexílica de Josué que significa ''él salva'', llevado por el sumo sacerdote y varios otros', 'Jesúa/Yeshúa — forma posexílica de Josué que significa ''él salva'', llevado por el sumo sacerdote y varios otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3444', 'spa', 'Salvación, liberación — el rescate divino del peligro o de los enemigos; en plural, los repetidos actos poderosos de victoria de Dios.', 'Salvación, liberación — el rescate divino del peligro o de los enemigos; en plural, los repetidos actos poderosos de victoria de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3446', 'spa', 'Isaac, hijo de Abraham y Sara, padre de Jacob y Esaú, patriarca de Israel', 'Isaac, cuyo nombre significa «él ríe», fue el hijo prometido que nació a Abraham y Sara en su vejez. Su nacimiento cumplió la promesa del pacto de Dios y provocó risa: tanto la risa incrédula de Sara al escuchar el anuncio como su risa gozosa al dar a luz. Segundo patriarca en el linaje de Israel, Isaac transmitió la bendición del pacto a Jacob en lugar de Esaú, continuando la línea por la cual todas las naciones serían bendecidas. Los profetas y salmistas invocan «el Dios de Abraham, Isaac y Jacob» como la fórmula del pacto que identifica al Dios de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3447', 'spa', 'extender, alargar, tender (el cetro de oro)', 'Verbo hebreo tardío (solo en la conjugación Hifil) que significa extender o alargar algo hacia alguien, de uso exclusivo en el libro de Ester. Las tres apariciones describen al rey persa extendiendo el cetro de oro: Ester 4:11 explica que quien se acerque al rey sin ser convocado morirá, a menos que el rey extienda el cetro; 5:2 narra al rey extendiéndolo hacia Ester; y 8:4 repite el gesto. El verbo procede del hebreo posbíblico y del arameo (Afel אוֹשֵׁיט), y podría estar relacionado con el árabe وَسَطَ. El acto de extender el cetro se convirtió en el gesto decisivo entre la vida y la muerte en la corte persa según Ester.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3448', 'spa', 'Isaí (Yishai) — padre betlemita del rey David, nieto de Rut y Booz.', 'Isaí (Yishai) — padre betlemita del rey David, nieto de Rut y Booz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3449', 'spa', 'Ishiya (Yishshiyyah/Yishshiyyahu), nombre propio que significa ''YHWH presta/no olvida'', llevado por varios levitas y guerreros', 'Ishiya (o Jishiya) es un nombre levítico y sacerdotal que aparece en Crónicas y Esdras, llevado por al menos cuatro individuos distintos. Un guerrero de Benjamín que se unió a David en Siclag porta la forma larga Yishshiyyahu (1 Cr 12:6). Entre los isacaritas, un jefe de clan lleva este nombre (1 Cr 7:3). Dos levitas coatitas figuran en los registros del servicio del templo (1 Cr 23:20; 24:21, 25). Finalmente, un Ishiya aparece entre quienes habían tomado mujeres extranjeras y aceptaron despedirlas (Esd 10:31). El significado del nombre, ''Yah presta'' o ''Yah no olvida'', se ajusta al papel de sus portadores en la adoración y la vida militar de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3452', 'spa', 'Páramo desolado o desierto; usado frecuentemente como cuasi-topónimo para la región desértica del Jesimón cerca del mar Muerto', 'Derivado de la raíz que significa ''estar desolado,'' este sustantivo pinta un cuadro vívido de terreno árido e inhabitable. Con el artículo definido funciona casi como nombre de lugar para el Jesimón, la árida región desértica que domina el mar Muerto donde David se escondió de Saúl (1 S 23:19, 24; 26:1, 3). Números lo usa para el páramo visible desde las alturas de Pisga y Peor (Nm 21:20; 23:28). Sin el artículo, adquiere una fuerza poética más abstracta, evocando desolación primordial en el ''yermo aullante'' de Deuteronomio 32:10 o el poder de Dios para hacer fluir ríos por el desierto (Is 43:19-20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3453', 'spa', 'anciano, envejecido; avanzado en años (usado solo en Job)', 'Este adjetivo aparece exclusivamente en el libro de Job para describir a personas ancianas, avanzadas en años. Job lo emplea para contrastar jóvenes y ancianos, señalando que tanto los canosos como los de edad avanzada se levantaban en su asamblea, o afirmando proverbialmente que la sabiduría reside «entre los ancianos». El joven Elihú usa este término para explicar por qué esperó respetuosamente para hablar, mostrando deferencia hacia quienes eran «ancianos» mientras él era «joven en días».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3455', 'spa', 'fue puesto, fue colocado (forma pasiva de ''poner/colocar'')', 'Forma verbal pasiva (Qal pasivo) que significa ''fue puesto'' o ''fue colocado'', presente en dos momentos clave de Génesis. En Génesis 24:33 (lectura Ketiv) se describe la comida que fue puesta ante el siervo de Abraham en casa de Labán, y en 50:26 se registra que el cuerpo de José fue colocado en un ataúd en Egipto. La forma representa una variante ortográfica y conjugacional del verbo común שׂוּם/שִׂים (poner, colocar, establecer). Las variantes Ketiv/Qeré y la relación de este verbo con el estándar שׂוּם evidencian la fluidez de las formas verbales en el hebreo bíblico, especialmente en verbos de alta frecuencia con múltiples raíces y grafías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3456', 'spa', 'quedar desolado, ser asolado (sinónimo de שָׁמֵם, solo en J, E y Ezequiel)', 'Este verbo, sinónimo del más frecuente שָׁמֵם, describe la tierra que queda desolada o asolada. Aparece en contextos de juicio y devastación: la tierra de Egipto plagada de ranas muertas, la tierra desolada por la sequía, los lugares altos destruidos, la tierra despojada de habitantes. Ezequiel emplea este término con especial frecuencia en sus oráculos contra Israel y las naciones circundantes, usándolo para retratar las consecuencias del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3458', 'spa', 'Yishmael — Ismael (''Dios oye''); hijo de Abraham y Agar, y varios otros personajes bíblicos', 'Yishmael — Ismael (''Dios oye''); hijo de Abraham y Agar, y varios otros personajes bíblicos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3459', 'spa', 'Ismaelita — adjetivo gentilicio que designa a los descendientes de Ismael o miembros de la confederación comercial ismaelita.', 'Este adjetivo gentilicio deriva del nombre propio Ismael y designa a los miembros del grupo tribal ismaelita. Los ismaelitas aparecen de forma memorable como los comerciantes de caravanas que compraron a José de manos de sus hermanos y lo llevaron a Egipto (Gn 37:25-28; 39:1), episodio que marcó toda la historia posterior de Israel. Jueces 8:24 identifica a los madianitas derrotados por Gedeón como vinculados a los ismaelitas. En las genealogías, Abigail, hermana de David, se casó con ''Jéter el ismaelita'' (1 Cr 2:17), y un ismaelita supervisaba los camellos reales (1 Cr 27:30). El Salmo 83:7 incluye a los ismaelitas entre los confederados hostiles contra Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3462', 'spa', 'Dormir, quedarse dormido; envejecer o volverse crónico (Nifal); hacer dormir a alguien, adormecer (Piel causativo)', 'Dormir, quedarse dormido; envejecer o volverse crónico (Nifal); hacer dormir a alguien, adormecer (Piel causativo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3463', 'spa', 'yashen -- dormido, que duerme; adjetivo que describe el estado de sueño, literal o figurado', 'El adjetivo yashen describe a alguien en estado de sueño. Desde Saúl tendido dormido en su campamento (1 Sam 26:7) hasta la declaración somnolienta de la amada ''yo duermo pero mi corazón vela'' (Cnt 5:2), abarca el sueño natural. Más allá del sentido literal, la palabra posee un notable peso figurado: Elías se burla de los sacerdotes de Baal insinuando que su dios simplemente está ''dormido'' (1 Re 18:27), y el salmista presenta a Yahvé despertando ''como uno que duerme'' para librar a su pueblo (Sal 78:65). De manera aún más llamativa, Daniel 12:2 habla de ''los que duermen en el polvo de la tierra'', los muertos que esperan la resurrección.');